function InvitationAvailabilityEditor({
  settings,
  setSettings,
}: {
  settings: AvailabilitySettings;
  setSettings: (updater: (current: AvailabilitySettings) => AvailabilitySettings) => void;
}) {
  const [useSameHours, setUseSameHours] = useState(false);

  function applyWindows(dayId: string, windows: AvailabilityTimeWindow[]) {
    setSettings((current) => {
      const targetDayIds = useSameHours ? new Set(current.preferredDays.length ? current.preferredDays : [dayId]) : new Set([dayId]);

      return {
        ...current,
        weeklySchedule: current.weeklySchedule.map((day) => {
          if (!targetDayIds.has(day.id)) {
            return day;
          }

          return {
            ...day,
            available: windows.length > 0,
            windows: day.id === dayId ? windows : windows.map((window, index) => cloneWindowForDay(day.id, window, index)),
          };
        }),
      };
    });
  }

  function togglePreferredDay(dayId: string) {
    setSettings((current) => {
      const selected = current.preferredDays.includes(dayId);

      return {
        ...current,
        preferredDays: selected
          ? current.preferredDays.filter((currentDayId) => currentDayId !== dayId)
          : [...current.preferredDays, dayId],
      };
    });
  }

  function addWindow(day: AvailabilityDaySetting) {
    const nextWindows = [
      ...day.windows,
      { end: "21:00", id: createAvailabilityWindowId(day.id), start: "18:00" },
    ];

    applyWindows(day.id, nextWindows);
  }

  function updateWindow(day: AvailabilityDaySetting, windowId: string, key: keyof AvailabilityTimeWindow, value: string) {
    applyWindows(day.id, day.windows.map((window) => window.id === windowId ? { ...window, [key]: value } : window));
  }

  function removeWindow(day: AvailabilityDaySetting, windowId: string) {
    applyWindows(day.id, day.windows.filter((window) => window.id !== windowId));
  }

  return (
    <InvitationEditorBlock title="Availability" subtitle="Set the days and times people can book with you.">
      <div className="grid gap-5">
        <div>
          <p className="text-sm font-black text-[#0F172A]">Meeting Hours</p>
          <div className="mt-3 flex flex-wrap gap-2">
            {invitationAvailabilityDayOptions.map((day) => {
              const selected = settings.preferredDays.includes(day.id);

              return (
                <button
                  aria-pressed={selected}
                  className={`flex h-10 w-10 items-center justify-center rounded-full border text-xs font-black transition-colors sm:h-12 sm:w-12 ${
                    selected
                      ? "border-[#2563EB] bg-[linear-gradient(135deg,#2563EB_0%,#1D4ED8_100%)] text-white shadow-[0_10px_20px_rgba(37,99,235,0.18)]"
                      : "border-[#DCEBFF] bg-white text-[#0F172A] hover:border-[#BFDBFE]"
                  }`}
                  key={day.id}
                  onClick={() => togglePreferredDay(day.id)}
                  type="button"
                >
                  {day.shortLabel}
                </button>
              );
            })}
          </div>
        </div>

        <div className="flex items-center justify-between gap-4">
          <span className="text-sm font-black text-[#0F172A]">Use same hours for all selected days</span>
          <button
            aria-pressed={useSameHours}
            aria-label="Use same hours for all selected days"
            className={`relative h-7 w-12 shrink-0 rounded-full transition-colors ${useSameHours ? "bg-[#2563EB]" : "bg-[#94A3B8]"}`}
            onClick={() => setUseSameHours((current) => !current)}
            type="button"
          >
            <span className={`absolute left-0 top-1 h-5 w-5 rounded-full bg-white shadow transition-transform ${useSameHours ? "translate-x-6" : "translate-x-1"}`} />
          </button>
        </div>

        <div className="flex items-center justify-between gap-3">
          <span className="text-sm font-black text-[#0F172A]">Time zone</span>
          <span className="inline-flex min-w-0 items-center gap-2 text-sm font-black text-[#1D4ED8]">
            <Globe2 className="h-4 w-4 shrink-0" aria-hidden="true" strokeWidth={1.9} />
            <span className="truncate">Central Time (CT)</span>
            <Pencil className="h-3.5 w-3.5 shrink-0" aria-hidden="true" strokeWidth={1.9} />
          </span>
        </div>

        <div className="grid gap-2">
          {settings.weeklySchedule.map((day) => (
            <div className="grid grid-cols-[88px_minmax(0,1fr)_34px_34px] items-center gap-2 sm:grid-cols-[104px_minmax(0,1fr)_36px_36px]" key={day.id}>
              <p className="truncate text-[13px] font-black text-[#0F172A] sm:text-sm">{day.label}</p>
              {day.available && day.windows.length ? (
                <div className="grid min-w-0 gap-2">
                  {day.windows.map((window) => (
                    <div className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-1 rounded-[10px] border border-[#DCEBFF] bg-white px-2 py-1.5" key={window.id}>
                      <input
                        aria-label={`${day.label} start time`}
                        className="min-w-0 bg-transparent text-center text-xs font-bold text-[#0F172A] outline-none"
                        inputMode="numeric"
                        onChange={(event) => updateWindow(day, window.id, "start", parseAvailabilityTimeInput(event.target.value, window.start))}
                        type="text"
                        value={formatAvailabilityTime(window.start)}
                      />
                      <span className="text-xs font-bold text-[#94A3B8]">-</span>
                      <input
                        aria-label={`${day.label} end time`}
                        className="min-w-0 bg-transparent text-center text-xs font-bold text-[#0F172A] outline-none"
                        inputMode="numeric"
                        onChange={(event) => updateWindow(day, window.id, "end", parseAvailabilityTimeInput(event.target.value, window.end))}
                        type="text"
                        value={formatAvailabilityTime(window.end)}
                      />
                    </div>
                  ))}
                </div>
              ) : (
                <span className="px-2 text-sm font-black text-[#94A3B8]">-</span>
              )}
              <button
                aria-label={`Add ${day.label} time window`}
                className="flex h-8 w-8 items-center justify-center rounded-full border border-[#CBD5E1] bg-white text-[#64748B] transition-colors hover:border-[#2563EB] hover:text-[#2563EB]"
                onClick={() => addWindow(day)}
                type="button"
              >
                <Plus className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
              </button>
              {day.available && day.windows.length ? (
                <button
                  aria-label={`Remove ${day.label} time window`}
                  className="flex h-8 w-8 items-center justify-center rounded-full text-[#94A3B8] transition-colors hover:bg-[#F8FAFC] hover:text-[#0F172A]"
                  onClick={() => removeWindow(day, day.windows.at(-1)?.id ?? "")}
                  type="button"
                >
                  <Trash2 className="h-4 w-4" aria-hidden="true" strokeWidth={1.8} />
                </button>
              ) : (
                <span aria-hidden="true" />
              )}
            </div>
          ))}
        </div>

        <button className="inline-flex w-fit items-center gap-2 rounded-full px-0 text-sm font-black text-[#1D4ED8]" type="button">
          <CalendarDays className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
          Add Date Override
        </button>
      </div>
    </InvitationEditorBlock>
  );
}

function InvitationDetailSheet({
  calendarConnection,
  calendarDisplaySettings,
  calendarSourceMessage,
  calendarSourcePreferences,
  invitation,
  inviteShareMessage,
  isDisconnecting,
  onClose,
  onCopy,
  onDisconnectCalendar,
  onOpenInvitation,
  onToggleCalendarCoreSource,
  onToggleGoogleCalendarSource,
  savingCalendarSourceId,
  setSettings,
  settings,
  workspaceDisplayName,
  workspaceId,
  workspaceSlug,
}: {
  calendarConnection: DosAppCalendarConnection;
  calendarDisplaySettings: CalendarDisplaySettings;
  calendarSourceMessage: string;
  calendarSourcePreferences: CalendarSourcePreference[];
  invitation: InviteCard;
  inviteShareMessage: string;
  isDisconnecting: boolean;
  onClose: () => void;
  onCopy: () => void;
  onDisconnectCalendar: () => void;
  onOpenInvitation: () => void;
  onToggleCalendarCoreSource: (source: CalendarCoreSource) => void;
  onToggleGoogleCalendarSource: (sourceId: string) => void;
  savingCalendarSourceId: string | null;
  setSettings: (updater: (current: AvailabilitySettings) => AvailabilitySettings) => void;
  settings: AvailabilitySettings;
  workspaceDisplayName: string;
  workspaceId: string;
  workspaceSlug: string;
}) {
  const [activeSection, setActiveSection] = useState<InvitationEditorSection>("availability");
  const [nameDraft, setNameDraft] = useState(invitation.title);
  const [descriptionDraft, setDescriptionDraft] = useState(invitation.description);
  const durationValue = settings.meetingTypes.find((type) => type.id === invitation.id)?.duration ?? invitation.durationMinutes;

  function updateDuration(value: number) {
    setSettings((current) => ({
      ...current,
      meetingTypes: current.meetingTypes.map((type) => type.id === invitation.id ? { ...type, duration: Math.max(15, value) } : type),
    }));
  }

  function updateBookingRule(key: keyof AvailabilitySettings["bookingRules"], value: number) {
    setSettings((current) => ({
      ...current,
      bookingRules: {
        ...current.bookingRules,
        [key]: Math.max(key === "bufferMinutes" ? 0 : 1, value),
      },
    }));
  }

  const activeContent = activeSection === "overview" ? (
    <InvitationEditorBlock title="Overview">
      <div className="grid gap-4">
        <label className="block">
          <FieldLabel>Name</FieldLabel>
          <input className={`${FieldInputClass()} min-h-11 rounded-[14px] px-3 text-sm`} onChange={(event) => setNameDraft(event.target.value)} value={nameDraft} />
        </label>
        <label className="block">
          <FieldLabel>Description</FieldLabel>
          <textarea className={`${FieldTextareaClass()} min-h-24 rounded-[14px] px-3 py-2 text-sm`} onChange={(event) => setDescriptionDraft(event.target.value)} value={descriptionDraft} />
        </label>
        <div className="grid gap-4 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-end">
          <label className="block">
            <FieldLabel>Duration</FieldLabel>
            <div className="mt-2 flex items-center gap-2">
              <input
                className={`${FieldInputClass(false)} min-h-11 rounded-[14px] px-3 text-sm`}
                min={15}
                onChange={(event) => updateDuration(Number(event.target.value) || 15)}
                step={15}
                type="number"
                value={durationValue}
              />
              <span className="shrink-0 text-xs font-bold text-[#64748B]">min</span>
            </div>
          </label>
          <div className="flex items-center gap-2">
            <span className="inline-flex min-h-10 items-center rounded-full border border-[#BBF7D0] bg-[#F0FDF4] px-3 text-xs font-bold text-[#15803D]">Active</span>
            <button className="inline-flex min-h-10 items-center rounded-full border border-[#BFDBFE] bg-[#EBF2FF] px-3 text-xs font-bold text-[#1D4ED8]" onClick={onCopy} type="button">
              <Link2 className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
              Copy Link
            </button>
          </div>
        </div>
      </div>
    </InvitationEditorBlock>
  ) : activeSection === "availability" ? (
    <InvitationAvailabilityEditor settings={settings} setSettings={setSettings} />
  ) : activeSection === "hosts" ? (
    <InvitationEditorBlock title="Hosts">
      <div className="grid gap-3">
        <InvitationStatusRow label={workspaceDisplayName} status="Single host" tone="green" />
        <InvitationStatusRow label="Spouse / household" status="Future" />
        <InvitationStatusRow label="Team invitations" status="Future" />
      </div>
    </InvitationEditorBlock>
  ) : activeSection === "questions" ? (
    <InvitationEditorBlock title="Questions">
      <div className="grid gap-3">
        {["Name", "Email", "Phone", "Notes", "Prayer request"].map((question) => (
          <InvitationStatusRow key={question} label={question} status={question === "Name" || question === "Email" ? "Required" : "Included"} tone={question === "Name" || question === "Email" ? "green" : "blue"} />
        ))}
      </div>
    </InvitationEditorBlock>
  ) : activeSection === "calendar" ? (
    <InvitationEditorBlock title="Calendar">
      <div className="grid gap-4">
        <CalendarConnectionCard
          calendarConnection={calendarConnection}
          isDisconnecting={isDisconnecting}
          onDisconnect={calendarConnection.connected ? onDisconnectCalendar : undefined}
          workspaceId={workspaceId}
          workspaceSlug={workspaceSlug}
        />
        <CalendarSourceControls
          calendarConnection={calendarConnection}
          displaySettings={calendarDisplaySettings}
          message={calendarSourceMessage}
          onToggleCoreSource={onToggleCalendarCoreSource}
          onToggleGoogleSource={onToggleGoogleCalendarSource}
          savingSourceId={savingCalendarSourceId}
          showMessage
          sourcePreferences={calendarSourcePreferences}
        />
        <div className="grid gap-3">
          <InvitationStatusRow label="Google Calendar" status={availabilityConnectionSummary(calendarConnection, calendarSourcePreferences.length)} tone={calendarConnectionIsHealthy(calendarConnection) ? "green" : "neutral"} />
          <InvitationStatusRow label="DOS Calendar" status="Active" tone="green" />
          <InvitationStatusRow label="Busy-time awareness" status="Planned" />
        </div>
      </div>
    </InvitationEditorBlock>
  ) : activeSection === "rules" ? (
    <InvitationEditorBlock title="Rules">
      <div className="grid gap-4">
        <div className="grid gap-3 sm:grid-cols-3">
          <InvitationRuleInput
            label="Buffer"
            onChange={(value) => updateBookingRule("bufferMinutes", value)}
            suffix="min"
            value={settings.bookingRules.bufferMinutes}
          />
          <InvitationRuleInput
            label="Maximum bookings"
            onChange={(value) => updateBookingRule("maxPerDay", value)}
            suffix="daily"
            value={settings.bookingRules.maxPerDay}
          />
          <InvitationRuleInput
            label="Weekly maximum"
            onChange={(value) => updateBookingRule("maxPerWeek", value)}
            suffix="weekly"
            value={settings.bookingRules.maxPerWeek}
          />
        </div>
        <div className="grid gap-3">
          <InvitationStatusRow label="Notice" status="12 hours" tone="blue" />
          <InvitationStatusRow label="Booking window" status="30 days" tone="blue" />
        </div>
      </div>
    </InvitationEditorBlock>
  ) : (
    <InvitationEditorBlock title="Sharing">
      <div className="grid gap-3 sm:grid-cols-2">
        <button className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full bg-[linear-gradient(135deg,#2563EB_0%,#1D4ED8_100%)] px-4 text-sm font-bold text-white shadow-[0_12px_26px_rgba(37,99,235,0.18)]" onClick={onCopy} type="button">
          <Link2 className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
          Copy Link
        </button>
        <button className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full border border-[#BFDBFE] bg-[#EBF2FF] px-4 text-sm font-bold text-[#1D4ED8]" onClick={onOpenInvitation} type="button">
          <ExternalLink className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
          Open Invitation
        </button>
        <button className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-[#E2E8F0] bg-white px-3 text-xs font-bold text-[#64748B]" disabled type="button">
          <Send className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
          Text
        </button>
        <button className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-[#E2E8F0] bg-white px-3 text-xs font-bold text-[#64748B]" disabled type="button">
          <Mail className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
          Email
        </button>
        <button className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-[#E2E8F0] bg-white px-3 text-xs font-bold text-[#64748B] sm:col-span-2" disabled type="button">
          <Square className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
          QR Code
        </button>
      </div>
    </InvitationEditorBlock>
  );

  return (
    <Sheet onClose={onClose} showHeader={false} size="wide" title={nameDraft || invitation.title}>
      <div className="flex max-h-[calc(100dvh-1.5rem)] flex-col overflow-hidden">
        <div className="mx-auto mt-3 h-1 w-10 shrink-0 rounded-full bg-[#E2E8F0] md:hidden" aria-hidden="true" />
        <header className="shrink-0 px-4 pt-4 sm:px-5">
          <div className="flex min-w-0 items-center gap-3">
            <button
              aria-label="Close invitation editor"
              className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-[#E2E8F0] bg-white text-[#0F172A] transition-colors hover:border-[#BFDBFE] hover:bg-[#F8FBFF]"
              onClick={onClose}
              type="button"
            >
              <ArrowLeft className="h-4 w-4" aria-hidden="true" strokeWidth={2} />
            </button>
            <div className="min-w-0 flex-1">
              <div className="flex min-w-0 items-center gap-2">
                <h2 className="truncate text-lg font-black leading-tight text-[#0F172A]">{nameDraft || invitation.title}</h2>
                <span className="shrink-0 rounded-full border border-[#BBF7D0] bg-[#F0FDF4] px-2.5 py-1 text-[10px] font-bold text-[#15803D]">Active</span>
              </div>
              <p className="mt-1 truncate text-xs font-semibold text-[#64748B]">{invitation.audience}</p>
            </div>
            <button
              className="hidden min-h-10 shrink-0 items-center gap-2 rounded-full border border-[#DCEBFF] bg-white px-3 text-xs font-black text-[#1D4ED8] transition-colors hover:border-[#BFDBFE] sm:inline-flex"
              onClick={onCopy}
              type="button"
            >
              <Link2 className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
              Copy Link
            </button>
            <button
              aria-label="Invitation options"
              className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-[#0F172A] transition-colors hover:bg-[#F8FBFF]"
              type="button"
            >
              <MoreHorizontal className="h-4 w-4" aria-hidden="true" strokeWidth={2} />
            </button>
          </div>
          {inviteShareMessage ? (
            <p className="mt-3 rounded-[16px] border border-[#DCEBFF] bg-[#F8FBFF] p-3 text-sm font-semibold leading-5 text-[#1D4ED8]">{inviteShareMessage}</p>
          ) : null}
          <InvitationEditorNav activeSection={activeSection} onChange={setActiveSection} />
        </header>

        <div className="min-h-0 flex-1 overflow-y-auto px-4 pb-[calc(env(safe-area-inset-bottom)+5.5rem)] pt-5 [scrollbar-width:none] sm:px-5 md:pb-5">
          <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_220px]">
            <div className="min-w-0">
              {activeContent}
            </div>
            <InvitationLivePreview duration={durationValue} invitation={invitation} name={nameDraft} settings={settings} />
          </div>
        </div>

        <footer className="shrink-0 border-t border-[#EAF2FF] bg-white px-4 pb-[calc(env(safe-area-inset-bottom)+0.75rem)] pt-3 sm:px-5 md:pb-4">
          <div className="flex items-center gap-3">
            <button
              className="inline-flex min-h-11 flex-1 items-center justify-center rounded-full bg-[linear-gradient(135deg,#2563EB_0%,#1D4ED8_100%)] px-4 text-sm font-bold text-white shadow-[0_12px_26px_rgba(37,99,235,0.18)] md:flex-none md:min-w-[150px]"
              onClick={onClose}
              type="button"
            >
              Save Changes
            </button>
            <button
              className="hidden min-h-11 items-center justify-center rounded-full px-4 text-sm font-bold text-[#1D4ED8] md:inline-flex"
              onClick={onClose}
              type="button"
            >
              Cancel
            </button>
          </div>
        </footer>
      </div>
    </Sheet>
  );
}

function DesktopInvitePanel({
  calendarConnection,
  calendarDisplaySettings,
  calendarSourceMessage,
  calendarSourcePreferences,
  isDisconnecting,
  onDisconnectCalendar,
  onToggleCalendarCoreSource,
  onToggleGoogleCalendarSource,
  savingCalendarSourceId,
  workspaceDisplayName,
  workspaceId,
  workspaceSlug,
}: {
  calendarConnection: DosAppCalendarConnection;
  calendarDisplaySettings: CalendarDisplaySettings;
  calendarSourceMessage: string;
  calendarSourcePreferences: CalendarSourcePreference[];
  isDisconnecting: boolean;
  onDisconnectCalendar: () => void;
  onToggleCalendarCoreSource: (source: CalendarCoreSource) => void;
  onToggleGoogleCalendarSource: (sourceId: string) => void;
  savingCalendarSourceId: string | null;
  workspaceDisplayName: string;
  workspaceId: string;
  workspaceSlug: string;
}) {
  const [inviteSettings, setInviteSettings] = useState<AvailabilitySettings>(() => createDefaultAvailabilitySettings());
  const [selectedInvitationId, setSelectedInvitationId] = useState<InviteCardKey | null>(null);
  const [inviteShareMessage, setInviteShareMessage] = useState("");
  const invitations = useMemo(() => createDefaultInvitationCards(inviteSettings), [inviteSettings]);
  const selectedInvitation = selectedInvitationId ? invitations.find((invitation) => invitation.id === selectedInvitationId) ?? null : null;

  async function copyInvitationLink(invitation: InviteCard) {
    try {
      await navigator.clipboard.writeText(invitationUrl(workspaceSlug, invitation.id));
      setInviteShareMessage(`${invitation.title} link copied.`);
    } catch {
      setInviteShareMessage("Copy link is unavailable in this browser.");
    }
  }

  function openInvitation(invitation: InviteCard) {
    window.open(invitationUrl(workspaceSlug, invitation.id), "_blank", "noopener,noreferrer");
  }

  return (
    <section className="min-w-0 rounded-[26px] border border-[#EAF2FF] bg-white/92 p-4 shadow-[0_12px_34px_rgba(37,99,235,0.045)] backdrop-blur md:p-5">
      <div className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <h2 className="text-2xl font-black leading-tight text-[#0F172A]" style={{ fontFamily: font.oswald }}>
            Your Invitations
          </h2>
          <p className="mt-2 max-w-2xl text-sm leading-6 text-[#64748B]">
            Create invitations people can use to find a time to meet with you.
          </p>
        </div>
        <span className="inline-flex w-fit items-center rounded-full border border-[#BBF7D0] bg-[#F0FDF4] px-3 py-1.5 text-xs font-bold text-[#15803D]">
          {invitations.length} Active
        </span>
      </div>

      {inviteShareMessage ? (
        <p className="mt-4 rounded-[18px] border border-[#DCEBFF] bg-[#F8FBFF] p-3 text-sm font-semibold leading-5 text-[#1D4ED8]">{inviteShareMessage}</p>
      ) : null}

      <div className="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {invitations.map((invitation) => (
          <InvitationCard
            invitation={invitation}
            key={invitation.id}
            onCopy={() => void copyInvitationLink(invitation)}
            onOpen={() => setSelectedInvitationId(invitation.id)}
          />
        ))}
      </div>

      <button
        className="mt-5 flex min-h-28 w-full flex-col items-center justify-center gap-2 rounded-[22px] border border-dashed border-[#BFDBFE] bg-[#F8FBFF] px-4 text-center text-sm font-black text-[#1D4ED8] transition-colors hover:border-[#2563EB] hover:bg-[#EBF2FF]"
        onClick={() => setSelectedInvitationId("kitchen_table")}
        type="button"
      >
        <span className="flex h-10 w-10 items-center justify-center rounded-full bg-[linear-gradient(135deg,#2563EB_0%,#1D4ED8_100%)] text-white shadow-[0_12px_24px_rgba(37,99,235,0.2)]">
          <Plus className="h-5 w-5" aria-hidden="true" strokeWidth={2} />
        </span>
        New Invitation
      </button>

      {selectedInvitation ? (
        <InvitationDetailSheet
          calendarConnection={calendarConnection}
          calendarDisplaySettings={calendarDisplaySettings}
          calendarSourceMessage={calendarSourceMessage}
          calendarSourcePreferences={calendarSourcePreferences}
          invitation={selectedInvitation}
          inviteShareMessage={inviteShareMessage}
          isDisconnecting={isDisconnecting}
          onClose={() => setSelectedInvitationId(null)}
          onCopy={() => void copyInvitationLink(selectedInvitation)}
          onDisconnectCalendar={onDisconnectCalendar}
          onOpenInvitation={() => openInvitation(selectedInvitation)}
          onToggleCalendarCoreSource={onToggleCalendarCoreSource}
          onToggleGoogleCalendarSource={onToggleGoogleCalendarSource}
          savingCalendarSourceId={savingCalendarSourceId}
          setSettings={setInviteSettings}
          settings={inviteSettings}
          workspaceDisplayName={workspaceDisplayName}
          workspaceId={workspaceId}
          workspaceSlug={workspaceSlug}
        />
      ) : null}
    </section>
  );
}

function DesktopPeopleIndex({
  empty,
  items,
  latestMeetingDateByPersonId,
  onOpenPerson,
  personTableStatsByPersonId,
  startIndex = 0,
  storyCountByPersonId,
}: {
  empty: string;
  items: CircleListItem[];
  latestMeetingDateByPersonId: Map<string, string | null>;
  onOpenPerson: (personId: string) => void;
  personTableStatsByPersonId: Map<string, PersonTableStats>;
  startIndex?: number;
  storyCountByPersonId: Map<string, number>;
}) {
  if (!items.length) {
    return (
      <div className="rounded-[24px] border border-[#EAF2FF] bg-white px-5 py-8 text-center text-sm text-[#64748B] shadow-[0_12px_34px_rgba(37,99,235,0.045)]">
        {empty}
      </div>
    );
  }

  return (
    <div className="hidden overflow-hidden rounded-[24px] border border-[#EAF2FF] bg-white shadow-[0_12px_34px_rgba(37,99,235,0.045)] md:block">
      <div className="overflow-x-auto">
        <div className="min-w-[980px]">
          <div className="grid grid-cols-[minmax(264px,1.7fr)_142px_122px_70px_112px_96px_116px] items-center gap-3 border-b border-[#EFF6FF] bg-[#F8FBFF] px-4 py-2.5 text-[10px] font-bold uppercase tracking-[0.14em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
            <span>Person</span>
            <span className="leading-[0.82rem]">
              <span className="block">Relationship</span>
              <span className="block">Context</span>
            </span>
            <span className="leading-[0.82rem]">
              <span className="block">Engagement</span>
              <span className="block">Level</span>
            </span>
            <span>Meetings</span>
            <span className="justify-self-center text-center leading-[0.82rem]">
              <span className="block">Time</span>
              <span className="block">Logged</span>
            </span>
            <span>Stories</span>
            <span className="leading-[0.82rem]">
              <span className="block">Last</span>
              <span className="block">Table</span>
            </span>
          </div>
          <div className="divide-y divide-[#EFF6FF]">
            {items.map((item, index) => {
              const { person } = item;
              const rowIndex = startIndex + index;
              const relationshipModel = personRelationshipModel(person);
              const lastTable = latestMeetingDateByPersonId.get(person.id) ?? null;
              const storyCount = storyCountByPersonId.get(person.id) ?? 0;
              const tableStats = personTableStatsByPersonId.get(person.id) ?? { meetings: 0, timeMinutes: 0 };

              return (
                <div
                  className="grid grid-cols-[minmax(264px,1.7fr)_142px_122px_70px_112px_96px_116px] items-center gap-3 px-4 py-3 text-xs transition-colors hover:bg-[#F8FBFF]"
                  key={person.id}
                >
                  <button className="flex min-w-0 items-center gap-3 text-left" onClick={() => onOpenPerson(person.id)} type="button">
                    <CircleAvatar index={rowIndex} person={person} size="sm" />
                    <span className="min-w-0">
                      <span className="block truncate text-sm font-black text-[#0F172A]">{person.name}</span>
                      <span className="mt-0.5 block truncate text-xs font-semibold text-[#64748B]">{relationshipTypePillLabel(person) || "—"}</span>
                    </span>
                  </button>
                  <span className="truncate text-[#475569]">{relationshipContextLabel(relationshipModel.relationshipContext) || "—"}</span>
                  <span className="truncate font-semibold text-[#334155]">{engagementLevelTableLabel(person)}</span>
                  <span className="font-black text-[#0F172A]">{tableStats.meetings}</span>
                  <span className="justify-self-center truncate text-center font-semibold text-[#475569]">{formatLoggedTime(tableStats.timeMinutes)}</span>
                  <span className="truncate font-black text-[#0F172A]">{storyCount} {storyCount === 1 ? "Story" : "Stories"}</span>
                  <span className="truncate font-semibold text-[#475569]">
                    {lastTable ? formatRelativeDate(lastTable) : "—"}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

function PersonCard({
  index,
  onClick,
  person,
  variant = "card",
}: {
  index: number;
  onClick?: () => void;
  person: DosAppPerson;
  variant?: "card" | "row";
}) {
  const isRow = variant === "row";
  const content = (
    <>
      <div className={`flex ${isRow ? "h-9 w-9" : "h-10 w-10"} shrink-0 items-center justify-center rounded-full text-xs font-semibold ${avatarTone(index)}`}>
        {initials(person.name)}
      </div>
      <div className="min-w-0 flex-1 text-left">
        <p className="truncate text-sm font-semibold text-[#0F172A]">{person.name}</p>
        <p className="mt-1 truncate text-xs text-[#64748B]">{relationshipLine(person)}</p>
      </div>
      {onClick ? <ChevronRight className="h-4 w-4 shrink-0 text-[#94A3B8]" aria-hidden="true" strokeWidth={1.8} /> : null}
    </>
  );

  if (onClick) {
    return (
      <button
        className={`flex w-full items-center gap-3 bg-white transition-colors hover:bg-[#FFFFFF] ${isRow ? "px-4 py-3" : "rounded-2xl border border-[#E2E8F0] px-4 py-3"}`}
        onClick={onClick}
        type="button"
      >
        {content}
      </button>
    );
  }

  return <article className={`flex items-center gap-3 bg-white ${isRow ? "px-4 py-3" : "rounded-2xl border border-[#E2E8F0] px-4 py-3"}`}>{content}</article>;
}

function circleDisplayName(circle: string) {
  switch (circle) {
    case "all":
      return "All Contacts";
    case "three":
      return "My 3";
    case "twelve":
      return "My 12";
    case "seventy":
      return "My 70";
    case "my_120":
      return "My 120";
    default:
      return "Field";
  }
}

function scoreLabel(value: number) {
  return `${Math.round(value)}`;
}

type CircleListItem = { person: DosAppPerson };
type CirclePersonItem = CircleListItem & { score: DosRelationshipScore };
type CircleLayerGroups = {
  my120: CirclePersonItem[];
  seventy: CirclePersonItem[];
  three: CirclePersonItem[];
  twelve: CirclePersonItem[];
};

function uniqueCircleMembers(items: CirclePersonItem[]) {
  const seen = new Set<string>();

  return items.filter((item) => {
    if (seen.has(item.person.id)) {
      return false;
    }

    seen.add(item.person.id);
    return true;
  });
}

function circleLayerDetails(activeCircle: CircleFocusView, circleGroups: CircleLayerGroups) {
  switch (activeCircle) {
    case "three":
      return {
        capacity: 3,
        cumulativeCount: circleGroups.three.length,
        empty: "No one in My 3 yet.",
        items: circleGroups.three,
        sectionLabel: "Top 3",
        startIndex: 0,
        subtitle: "The people you invest in most deeply.",
        title: "My 3",
        value: "3",
      };
    case "twelve":
      return {
        capacity: 9,
        cumulativeCount: circleGroups.twelve.length,
        empty: "No additional people in your 12 yet.",
        items: circleGroups.twelve,
        sectionLabel: "Next 9 People",
        startIndex: 3,
        subtitle: "These are the next 9 people in your core circle.",
        title: "My 12",
        value: "12",
      };
    case "seventy":
      return {
        capacity: 58,
        cumulativeCount: circleGroups.seventy.length,
        empty: "No additional people in your 70 yet.",
        items: circleGroups.seventy,
        sectionLabel: "Next 58 People",
        startIndex: 12,
        subtitle: "These are the next 58 people in your broader field.",
        title: "My 70",
        value: "70",
      };
    case "my_120":
      return {
        capacity: 50,
        cumulativeCount: circleGroups.my120.length,
        empty: "No additional people in your 120 yet.",
        items: circleGroups.my120,
        sectionLabel: "Next 50 People",
        startIndex: 70,
        subtitle: "These are the next 50 people in your extended field.",
        title: "My 120",
        value: "120",
      };
  }
}

function previewCircleLayerItems(activeCircle: CircleFocusView, items: CirclePersonItem[]) {
  return activeCircle === "seventy" || activeCircle === "my_120" ? items.slice(0, 6) : items;
}

function peopleCircleDetails(activeCircle: PeopleCircleView, circleGroups: CircleLayerGroups, allItems: CircleListItem[]) {
  if (activeCircle === "all") {
    return {
      empty: "No field contacts yet.",
      items: allItems,
      sectionLabel: "All Contacts",
      startIndex: 0,
      subtitle: "Everyone currently saved in your field.",
      title: "All Contacts",
    };
  }

  const details = circleLayerDetails(activeCircle, circleGroups);

  return {
    empty: details.empty,
    items: details.items,
    sectionLabel: details.sectionLabel,
    startIndex: details.startIndex,
    subtitle: details.subtitle,
    title: details.title,
  };
}

function filterCircleItems(items: CircleListItem[], query: string) {
  const filtered = filteredPeople(items.map(({ person }) => person), query);
  const filteredIds = new Set(filtered.map((person) => person.id));

  return items.filter(({ person }) => filteredIds.has(person.id));
}

function CircleAvatar({
  index,
  layer,
  person,
  size = "md",
}: {
  index: number;
  layer?: "center" | "middle" | "outer";
  person?: DosAppPerson;
  size?: "lg" | "md" | "sm" | "xs";
}) {
  const sizeClass = {
    lg: "h-11 w-11 text-sm",
    md: "h-10 w-10 text-xs",
    sm: "h-8 w-8 text-[10px]",
    xs: "h-6 w-6 text-[8px]",
  }[size];

  if (!person) {
    return (
      <span className={`${sizeClass} flex shrink-0 items-center justify-center rounded-full border border-dashed border-[#E2E8F0] bg-[#F1F5F9] text-[#94A3B8]`}>
        +
      </span>
    );
  }

  return (
    <span
      className={`${sizeClass} flex shrink-0 items-center justify-center rounded-full font-bold ${avatarTone(index)}`}
      data-circle-layer={layer}
      data-person-id={person.id}
    >
      {initials(person.name)}
    </span>
  );
}

