function MeetingCard({
  meeting,
  onClick,
  people,
}: {
  meeting: DosAppMeeting;
  onClick: () => void;
  people: DosAppPerson[];
}) {
  const avatarNames = meetingAvatarNames(meeting, people);
  const participantTitle = meetingParticipantTitle(meeting, people);
  const hasPeople = Boolean(participantTitle);
  const context = meetingActivityTitle(meeting);
  const isScheduled = meeting.meetingStatus === "scheduled";
  const summary = meeting.notes?.trim();
  const title = meetingDisplayTitle(meeting, people);
  const statusLabel = isScheduled ? "Scheduled" : "Logged";
  const metadata = isScheduled
    ? `Scheduled • ${formatMeetingTimeRange(meeting)}`
    : hasPeople ? `${context} • ${formatDate(meeting.date)}` : formatDate(meeting.date);

  return (
    <button className="group w-full max-w-[calc(100vw-32px)] rounded-[24px] border border-[#EAF2FF] bg-white p-3.5 text-left shadow-[0_14px_34px_rgba(37,99,235,0.045)] transition-all hover:border-[#BFDBFE] hover:shadow-[0_18px_40px_rgba(37,99,235,0.08)] md:max-w-none md:rounded-[20px] md:p-3 md:shadow-[0_10px_28px_rgba(37,99,235,0.04)]" onClick={onClick} type="button">
      <div className="flex items-start gap-3">
        <div className="mt-0.5 flex shrink-0 items-center">
          {avatarNames.length ? (
            <div className="flex -space-x-2">
              {avatarNames.map((name, index) => (
                <span
                  className={`flex h-8 w-8 items-center justify-center rounded-full border-2 border-white text-[9px] font-bold shadow-sm ${avatarTone(index)}`}
                  key={`${meeting.id}-${name}`}
                >
                  {initials(name)}
                </span>
              ))}
            </div>
          ) : (
            <span className="flex h-8 w-8 items-center justify-center rounded-full border border-[#BFDBFE] bg-[#EFF6FF] text-[#2563EB] shadow-sm">
              <MessageCircle className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={2} />
            </span>
          )}
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <p className="truncate text-[15px] font-bold leading-5 text-[#0F172A]">{title}</p>
              <p className="mt-1 truncate text-xs leading-5 text-[#64748B]">{metadata}</p>
            </div>
            <ChevronRight className="mt-1 h-4 w-4 shrink-0 text-[#94A3B8] transition-colors group-hover:text-[#2563EB]" aria-hidden="true" strokeWidth={1.8} />
          </div>
          <div className="mt-2 flex flex-wrap gap-1.5">
            <span className="rounded-full bg-[#EBF2FF] px-2.5 py-1 text-[9px] font-bold uppercase tracking-[0.1em] text-[#1D4ED8]" style={{ fontFamily: font.rajdhani }}>
              {context}
            </span>
            <span className="rounded-full border border-[#E2E8F0] bg-white px-2.5 py-1 text-[9px] font-bold uppercase tracking-[0.1em] text-[#64748B]" style={{ fontFamily: font.rajdhani }}>
              {statusLabel}
            </span>
          </div>
          {summary ? (
            <p className="mt-2 line-clamp-2 text-sm leading-5 text-[#334155] md:text-[13px]">{summary}</p>
          ) : (
            <p className="mt-2 text-sm leading-5 text-[#94A3B8] md:text-[13px]">{isScheduled ? "No prep notes yet" : "No reflection yet"}</p>
          )}
          {isScheduled && meeting.googleSyncEnabled ? (
            <span className="mt-2 inline-flex rounded-full border border-[#BFDBFE] bg-[#EBF2FF] px-2 py-0.5 text-[10px] font-bold text-[#1D4ED8]">
              {meeting.googleSyncStatus === "synced" ? "Google synced" : meeting.googleSyncStatus === "failed" ? "Google failed" : "Google pending"}
            </span>
          ) : null}
        </div>
      </div>
    </button>
  );
}

function calendarItemTone(kind: MeetingCalendarItemKind) {
  switch (kind) {
    case "google":
      return {
        bg: "bg-[#EEF6FF]",
        dot: "bg-[#0EA5E9]",
        text: "text-[#0369A1]",
      };
    case "birthday":
      return {
        bg: "bg-[#DCFCE7]",
        dot: "bg-[#16A34A]",
        text: "text-[#15803D]",
      };
    case "anniversary":
      return {
        bg: "bg-[#EAF2FF]",
        dot: "bg-[#2563EB]",
        text: "text-[#1D4ED8]",
      };
    case "follow_up":
      return {
        bg: "bg-[#DCFCE7]",
        dot: "bg-[#16A34A]",
        text: "text-[#15803D]",
      };
    case "prayer":
      return {
        bg: "bg-[#DCFCE7]",
        dot: "bg-[#16A34A]",
        text: "text-[#15803D]",
      };
    case "meeting":
    default:
      return {
        bg: "bg-[#EBF2FF]",
        dot: "bg-[#2563EB]",
        text: "text-[#1D4ED8]",
      };
  }
}

function calendarItemLabel(kind: MeetingCalendarItemKind) {
  switch (kind) {
    case "google":
      return "Google";
    case "birthday":
      return "Birthday";
    case "anniversary":
      return "Anniversary";
    case "follow_up":
      return "Follow Up";
    case "prayer":
      return "Prayer";
    case "meeting":
    default:
      return "Table";
  }
}

function CalendarItemIcon({ kind }: { kind: MeetingCalendarItemKind }) {
  const className = "h-4 w-4";

  switch (kind) {
    case "google":
      return <CalendarDays className={className} aria-hidden="true" strokeWidth={1.9} />;
    case "birthday":
      return <Cake className={className} aria-hidden="true" strokeWidth={1.9} />;
    case "anniversary":
      return <HeartHandshake className={className} aria-hidden="true" strokeWidth={1.9} />;
    case "follow_up":
      return <Send className={className} aria-hidden="true" strokeWidth={1.9} />;
    case "prayer":
      return <Heart className={className} aria-hidden="true" strokeWidth={1.9} />;
    case "meeting":
    default:
      return <CalendarDays className={className} aria-hidden="true" strokeWidth={1.9} />;
  }
}

function calendarItemSourceLabel(item: MeetingCalendarItem) {
  if (item.kind === "google") {
    return "Google";
  }

  if (item.kind === "meeting") {
    return "DOS";
  }

  return "Reminder";
}

function calendarItemTypeLabel(item: MeetingCalendarItem) {
  if (item.meeting) {
    return meetingActivityTitle(item.meeting);
  }

  return calendarItemLabel(item.kind);
}

function calendarUpcomingCardHeadline(item: MeetingCalendarItem) {
  if (item.kind === "google") {
    return item.title || googleCalendarUntitledEventLabel;
  }

  return item.title || calendarItemPersonLabel(item);
}

function calendarItemPersonLabel(item: MeetingCalendarItem) {
  if (item.personName) {
    return item.personName;
  }

  if (item.externalEvent) {
    return googleCalendarSourceMetadata(item.externalEvent);
  }

  return "No person linked";
}

function calendarItemDateTimeLabel(item: MeetingCalendarItem) {
  if (item.meeting) {
    return formatMeetingTimeRange(item.meeting);
  }

  if (item.externalEvent) {
    return formatExternalCalendarEventTimeRange(item.externalEvent);
  }

  return formatDateTime(item.date);
}

function calendarCompactDayLabel(value: string | null) {
  const date = parseDisplayDate(value);

  if (!date) {
    return "Soon";
  }

  const today = displayDayStart(new Date());
  const eventDay = displayDayStart(date);
  const dayDiff = today && eventDay
    ? Math.round((eventDay.getTime() - today.getTime()) / (24 * 60 * 60 * 1000))
    : null;

  if (dayDiff === 0) {
    return "Today";
  }

  if (dayDiff === 1) {
    return "Tomorrow";
  }

  if (dayDiff !== null && dayDiff > 1 && dayDiff < 7) {
    return new Intl.DateTimeFormat("en-US", { timeZone: dosDisplayTimeZone, weekday: "short" }).format(date);
  }

  return new Intl.DateTimeFormat("en-US", { day: "numeric", month: "short", timeZone: dosDisplayTimeZone }).format(date);
}

function calendarUpcomingCardTimeLabel(item: MeetingCalendarItem) {
  const day = calendarCompactDayLabel(item.date);

  if (item.externalEvent?.allDay) {
    return day;
  }

  const time = formatTime(item.date);

  return [day, time].filter(Boolean).join(" · ");
}

function calendarItemNotes(item: MeetingCalendarItem) {
  if (item.meeting?.notes?.trim()) {
    return item.meeting.notes.trim();
  }

  if (item.reminder?.notes?.trim()) {
    return reminderVisibleNotes(item.reminder.notes);
  }

  if (item.externalEvent?.description?.trim()) {
    return item.externalEvent.description.trim();
  }

  return "";
}

function calendarItemSourceTone(item: MeetingCalendarItem) {
  if (item.kind === "google") {
    return "border-[#BAE6FD] bg-[#F0F9FF] text-[#0369A1]";
  }

  if (item.kind === "meeting") {
    return "border-[#BFDBFE] bg-[#EBF2FF] text-[#1D4ED8]";
  }

  return "border-[#BBF7D0] bg-[#F0FDF4] text-[#15803D]";
}

function calendarQuickPrimaryActionLabel(item: MeetingCalendarItem) {
  if (item.kind === "meeting") {
    return "Log Table";
  }

  if (item.kind === "google") {
    return "View Details";
  }

  return "Mark Done";
}

function calendarNeedsReviewPrimaryActionLabel(item: MeetingCalendarItem) {
  if (item.kind === "meeting") {
    return "Log Table";
  }

  if (item.kind === "google") {
    return "Add to DOS";
  }

  return "Mark Done";
}

function calendarNeedsReviewSecondaryActionLabel(item: MeetingCalendarItem) {
  if (item.kind === "google") {
    return "Dismiss";
  }

  if (item.kind === "meeting") {
    return "Reschedule";
  }

  return "Edit";
}

function calendarQuickSecondaryActionLabel(item: MeetingCalendarItem) {
  return item.meeting || item.reminder ? "Edit" : null;
}

function calendarWeekHourLabel(hour: number) {
  if (hour === 12) {
    return "12 PM";
  }

  return hour > 12 ? `${hour - 12} PM` : `${hour} AM`;
}

function calendarItemMinuteOfDay(item: MeetingCalendarItem) {
  const date = parseDisplayDate(item.date);

  if (!date || item.externalEvent?.allDay) {
    return 9 * 60;
  }

  return date.getHours() * 60 + date.getMinutes();
}

function calendarItemDurationMinutes(item: MeetingCalendarItem) {
  if (item.meeting) {
    return Math.max(30, tableDurationMinutes(item.meeting) || 60);
  }

  if (item.externalEvent?.endAt) {
    const start = parseDisplayDate(item.externalEvent.startAt);
    const end = parseDisplayDate(item.externalEvent.endAt);

    if (start && end && end.getTime() > start.getTime()) {
      return Math.max(30, Math.round((end.getTime() - start.getTime()) / 60000));
    }
  }

  return item.kind === "birthday" || item.kind === "anniversary" ? 30 : 60;
}

