function prayerDetailSourceLabel(detail: PrayerDetail) {
  if (detail.kind === "reminder") {
    return "Manual";
  }

  return detail.source === "Leader reflection" ? "Leader Reflection" : detail.source;
}

function PrayerDetailSheet({
  detail,
  onClose,
  onMarkAnswered,
  onMarkPrayed,
  onOpenMeeting,
  onOpenPerson,
}: {
  detail: PrayerDetail;
  onClose: () => void;
  onMarkAnswered: (reminderId: string) => void;
  onMarkPrayed: (detail: PrayerDetail, note: string) => void;
  onOpenMeeting: (meetingId: string) => void;
  onOpenPerson: (personId: string) => void;
}) {
  const [prayerNote, setPrayerNote] = useState("");
  const statusLabel = detail.status === "answered" ? "Answered" : "Praying";
  const canMarkAnswered = detail.kind === "reminder" && detail.status === "praying";
  const runAndClose = (action: () => void) => {
    onClose();
    action();
  };

  return (
    <Sheet onClose={onClose} showEyebrow={false} title={detail.request}>
      <div className="space-y-4">
        <div className="flex flex-wrap gap-2">
          <DesktopPrayerStatusPill>{statusLabel}</DesktopPrayerStatusPill>
          <span className="rounded-full border border-[#DCEBFF] bg-white px-3 py-1 text-[10px] font-bold uppercase tracking-[0.14em] text-[#64748B]" style={{ fontFamily: font.rajdhani }}>
            {prayerDetailSourceLabel(detail)}
          </span>
        </div>

        <section className={meetingFormGroupClassName}>
          <div className={meetingFormGroupCardClassName}>
            <FieldLabel>Prayer Request</FieldLabel>
            <p className="mt-3 whitespace-pre-line text-base font-black leading-7 text-[#0F172A]">{detail.request}</p>
            {detail.notes ? <p className="mt-3 whitespace-pre-line text-sm leading-6 text-[#475569]">{detail.notes}</p> : null}
            <div className="mt-3 divide-y divide-[#E2E8F0] overflow-hidden rounded-[20px] border border-[#E2E8F0] bg-[#F8FAFC]">
              <PrayerDetailMetaRow label="Person" value={detail.personName} />
              {detail.meetingId ? <PrayerDetailMetaRow label="Related Table" value={detail.meetingLabel ?? "Linked table"} /> : null}
              <PrayerDetailMetaRow label="Frequency" value={detail.frequency} />
              <PrayerDetailMetaRow label="Last Prayed" value={detail.lastPrayedAt ? formatDate(detail.lastPrayedAt) : "Not yet"} />
              <PrayerDetailMetaRow label={detail.status === "answered" ? "Answered" : "Added"} value={formatDate(detail.answeredAt ?? detail.createdAt)} />
            </div>
          </div>
        </section>

        <DosFormSection icon="log" title="Prayer Log">
          <DosFormField label="Private Note">
            <VoiceTextarea
              className={`${FieldTextareaClass()} min-h-24`}
              onChange={(event) => setPrayerNote(event.target.value)}
              placeholder="What did you pray or notice?"
              value={prayerNote}
            />
          </DosFormField>
        </DosFormSection>

        <div className="grid gap-2">
          <AppButton icon="prayer" onClick={() => onMarkPrayed(detail, prayerNote)} tone="black">Prayed Today</AppButton>
          {canMarkAnswered ? (
            <AppButton onClick={() => runAndClose(() => onMarkAnswered(detail.sourceId))} tone="white">Mark Answered</AppButton>
          ) : null}
          <div className="grid gap-2 min-[420px]:grid-cols-2">
            {detail.personId ? (
              <AppButton icon="people" onClick={() => runAndClose(() => onOpenPerson(detail.personId!))} tone="white">Open Person</AppButton>
            ) : null}
            {detail.meetingId ? (
              <AppButton icon="calendar" onClick={() => runAndClose(() => onOpenMeeting(detail.meetingId!))} tone="white">Open Table</AppButton>
            ) : null}
          </div>
          <AppButton onClick={onClose} tone="white">Close</AppButton>
        </div>
      </div>
    </Sheet>
  );
}

function MobilePrayerPanel({
  children,
  eyebrow,
  emptyText,
  emptyTitle,
  hasRows,
}: {
  children: ReactNode;
  eyebrow: string;
  emptyText: string;
  emptyTitle: string;
  hasRows: boolean;
}) {
  return (
    <section className="rounded-[24px] border border-[#EAF2FF] bg-white p-3 shadow-[0_12px_30px_rgba(37,99,235,0.045)]">
      <h2 className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#2563EB]" style={{ fontFamily: font.rajdhani }}>
        {eyebrow}
      </h2>
      <div className="mt-3">
        {hasRows ? children : <EmptyState text={emptyText} title={emptyTitle} />}
      </div>
    </section>
  );
}

function MobilePrayerWorkspace({
  householdMembers,
  localPrayerPartners,
  onOpenPrayerPartner,
  onOpenPrayerDetail,
  onOpenPrayerRequest,
  onUpdatePrayerTeamCountVisibility,
  prayerPartners,
  prayerRows,
  prayerRequests,
  query,
  showPrayerTeamCount,
  tab,
  onTabChange,
}: {
  householdMembers: DosAppHouseholdMember[];
  localPrayerPartners: LocalPrayerPartner[];
  onOpenPrayerDetail: (detail: PrayerDetail) => void;
  onOpenPrayerPartner: (partner: LocalPrayerPartner) => void;
  onOpenPrayerRequest: (request: DosAppPrayerRequest) => void;
  onTabChange: (value: PrayerWorkspaceTab) => void;
  onUpdatePrayerTeamCountVisibility: (value: boolean) => Promise<void>;
  prayerPartners: DosAppPrayerPartner[];
  prayerRows: PrayerDetail[];
  prayerRequests: DosAppPrayerRequest[];
  query: string;
  showPrayerTeamCount: boolean;
  tab: PrayerWorkspaceTab;
}) {
  const [prayingForView, setPrayingForView] = useState<PrayerRequestView>("praying");
  const [prayerRequestView, setPrayerRequestView] = useState<PrayerRequestView>("praying");
  const prayerSearch = query.trim().toLowerCase();
  const matchesPrayerSearch = (...values: Array<null | string | undefined>) => {
    if (!prayerSearch) {
      return true;
    }

    return values
      .filter(Boolean)
      .join(" ")
      .toLowerCase()
      .includes(prayerSearch);
  };
  const loadedPrayerPartnerRows = (prayerPartners ?? []).map(mapDosPrayerPartnerToLocal);
  const prayerPartnerRows = mergeRowsById(
    localPrayerPartners,
    loadedPrayerPartnerRows.length || localPrayerPartners.length ? loadedPrayerPartnerRows : [...desktopPrayerPartnerSamples],
  );
  const prayerRequestById = new Map(prayerRequests.map((request) => [request.id, request]));
  const prayerRequestRows = (prayerRequests ?? []).map(mapDosPrayerRequestToLocal);
  const visiblePrayerRows = prayerRows.filter((row) => (
    row.status === prayingForView
    && matchesPrayerSearch(
      row.personName,
      row.request,
      row.notes,
      row.source,
      row.frequency,
      row.status === "answered" ? "Answered" : "Praying",
      row.lastPrayedAt ? formatRelativeDate(row.lastPrayedAt) : undefined,
      row.answeredAt ? formatRelativeDate(row.answeredAt) : undefined,
      row.createdAt ? formatRelativeDate(row.createdAt) : undefined,
    )
  ));
  const visiblePrayerRequests = prayerRequestRows.filter((request) => (
    request.view === prayerRequestView
    && matchesPrayerSearch(request.request, request.category, request.sharedWith, request.status, request.created, request.answered)
  ));
  const visiblePrayerPartners = prayerPartnerRows.filter((partner) => (
    normalizePrayerPartnerStatus(partner.status) !== "archived"
    && matchesPrayerSearch(
      partner.name,
      partner.relationship,
      prayerPartnerTeamLabel(partner.prayerTeam, householdMembers),
      prayerPartnerHowJoinedLabel(partner.howHeard),
      partner.status,
      partner.lastContacted,
      partner.notes,
    )
  ));

  return (
    <div className="space-y-3 md:hidden">
      <SegmentedTabs onChange={onTabChange} options={prayerWorkspaceTabs} value={tab} />

      {tab === "praying_for" ? (
        <MobilePrayerPanel
          emptyText={prayingForView === "answered" ? "Answered prayer will appear here after a request is marked answered." : "Prayer needs from logged tables and prayer reminders will appear here."}
          emptyTitle={prayingForView === "answered" ? "No answered prayer yet." : "No prayer requests yet."}
          eyebrow="Praying For"
          hasRows={visiblePrayerRows.length > 0}
        >
          <div className="mb-3 max-w-[18rem]">
            <SegmentedTabs onChange={setPrayingForView} options={prayerRequestViewTabs} value={prayingForView} />
          </div>
          <div className="overflow-hidden rounded-[22px] border border-[#EAF2FF]">
            <div className="grid grid-cols-[76px_minmax(0,1fr)_72px] gap-2 bg-[#F8FBFF] px-3 py-2 text-[10px] font-bold uppercase tracking-[0.14em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
              <span>Person</span>
              <span>Request</span>
              <span>Status</span>
            </div>
            {visiblePrayerRows.map((row) => (
              <button
                className="grid min-h-[64px] w-full grid-cols-[76px_minmax(0,1fr)_72px] items-center gap-2 border-t border-[#EAF2FF] px-3 py-2 text-left"
                key={row.id}
                onClick={() => onOpenPrayerDetail(row)}
                type="button"
              >
                <span className="truncate text-xs font-bold text-[#0F172A]">{row.personName}</span>
                <span className="min-w-0">
                  <span className="block truncate text-sm font-black text-[#0F172A]">{row.request}</span>
                  <span className="mt-0.5 block truncate text-xs text-[#64748B]">{row.frequency}</span>
                </span>
                <DesktopPrayerStatusPill>{row.status === "answered" ? "Answered" : "Praying"}</DesktopPrayerStatusPill>
              </button>
            ))}
          </div>
        </MobilePrayerPanel>
      ) : null}

      {tab === "my_requests" ? (
        <MobilePrayerPanel
          emptyText={prayerRequestView === "answered" ? "Answered requests will appear here." : "Add a prayer request to begin tracking it."}
          emptyTitle={prayerRequestView === "answered" ? "No answered requests." : "No prayer requests."}
          eyebrow="My Requests"
          hasRows={visiblePrayerRequests.length > 0}
        >
          <div className="mb-3 max-w-[18rem]">
            <SegmentedTabs onChange={setPrayerRequestView} options={prayerRequestViewTabs} value={prayerRequestView} />
          </div>
          <div className="overflow-hidden rounded-[22px] border border-[#EAF2FF]">
            <div className="grid grid-cols-[minmax(0,1fr)_78px_58px] gap-2 bg-[#F8FBFF] px-3 py-2 text-[10px] font-bold uppercase tracking-[0.14em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
              <span>Request</span>
              <span>Status</span>
              <span>Date</span>
            </div>
            {visiblePrayerRequests.map((request) => (
              <button
                className="grid min-h-[62px] w-full grid-cols-[minmax(0,1fr)_78px_58px] items-center gap-2 border-t border-[#EAF2FF] px-3 py-2 text-left transition-colors hover:bg-[#F8FBFF] focus:outline-none focus-visible:bg-[#F8FBFF]"
                key={request.id}
                onClick={() => {
                  const selectedRequest = prayerRequestById.get(request.id);

                  if (selectedRequest) {
                    onOpenPrayerRequest(selectedRequest);
                  }
                }}
                type="button"
              >
                <span className="min-w-0">
                  <span className="block truncate text-sm font-black text-[#0F172A]">{request.request}</span>
                  <span className="mt-0.5 block truncate text-xs text-[#64748B]">{request.category}</span>
                </span>
                <DesktopPrayerStatusPill>{request.status}</DesktopPrayerStatusPill>
                <span className="truncate text-xs font-bold text-[#475569]">{prayerRequestView === "answered" ? request.answered : request.created}</span>
              </button>
            ))}
          </div>
        </MobilePrayerPanel>
      ) : null}

      {tab === "partners" ? (
        <MobilePrayerPanel
          emptyText="Prayer partners will appear here after they are added."
          emptyTitle="No prayer partners yet."
          eyebrow="Prayer Team"
          hasRows={visiblePrayerPartners.length > 0}
        >
          <div className="mb-3">
            <PrayerTeamCountVisibilityToggle checked={showPrayerTeamCount} onChange={onUpdatePrayerTeamCountVisibility} />
          </div>
          <div className="overflow-hidden rounded-[22px] border border-[#EAF2FF]">
            <div className="grid grid-cols-[minmax(0,1fr)_82px_72px] gap-2 bg-[#F8FBFF] px-3 py-2 text-[10px] font-bold uppercase tracking-[0.14em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
              <span>Name</span>
              <span>Status</span>
              <span>Last</span>
            </div>
            {visiblePrayerPartners.map((partner) => (
              <button
                className="grid min-h-[62px] w-full grid-cols-[minmax(0,1fr)_82px_72px] items-center gap-2 border-t border-[#EAF2FF] px-3 py-2 text-left transition-colors hover:bg-[#F8FBFF] focus:outline-none focus-visible:bg-[#F8FBFF]"
                key={`${partner.id}-${partner.name}`}
                onClick={() => onOpenPrayerPartner(partner)}
                type="button"
              >
                  <span className="min-w-0">
                    <span className="block truncate text-sm font-black text-[#0F172A]">{partner.name}</span>
                    <span className="mt-0.5 block truncate text-xs text-[#64748B]">{partner.relationship} · {prayerPartnerTeamLabel(partner.prayerTeam, householdMembers)}</span>
                  </span>
                <DesktopPrayerStatusPill>{partner.status}</DesktopPrayerStatusPill>
                <span className="truncate text-xs font-bold text-[#475569]">{partner.lastContacted}</span>
              </button>
            ))}
          </div>
        </MobilePrayerPanel>
      ) : null}
    </div>
  );
}

function DesktopPrayerWorkspace({
  actionsHidden = false,
  answeredPrayerByReminderId,
  householdMembers,
  leaderReflections,
  localPrayerNeeds,
  meetings,
  onSearchChange,
  onCreatePrayerRequest,
  onDeletePrayerPartner,
  onDeletePrayerRequest,
  onMarkPrayerAnswered,
  onOpenMeeting,
  onOpenPerson,
  onScheduleMeeting,
  onCreatePrayerPartner,
  onUpdatePrayerPartner,
  onUpdatePrayerTeamCountVisibility,
  onUpdatePrayerRequest,
  people,
  prayerPartners,
  prayerRequests,
  query,
  reminders,
  showPrayerTeamCount,
  tab,
  onTabChange,
}: {
  actionsHidden?: boolean;
  answeredPrayerByReminderId: Record<string, string>;
  householdMembers: DosAppHouseholdMember[];
  leaderReflections: DosAppLeaderReflection[];
  localPrayerNeeds: LocalPrayerNeed[];
  meetings: DosAppMeeting[];
  onCreatePrayerRequest: (draft: DosPrayerRequestDraft) => Promise<DosAppPrayerRequest>;
  onDeletePrayerPartner: (partner: LocalPrayerPartner) => Promise<string>;
  onDeletePrayerRequest: (id: string) => Promise<string>;
  onMarkPrayerAnswered: (reminderId: string) => void;
  onOpenMeeting: (meetingId: string) => void;
  onOpenPerson: (personId: string) => void;
  onScheduleMeeting: () => void;
  onCreatePrayerPartner: (patch: DosPrayerPartnerPatch) => Promise<LocalPrayerPartner>;
  onSearchChange: (value: string) => void;
  onTabChange: (value: PrayerWorkspaceTab) => void;
  onUpdatePrayerPartner: (partner: LocalPrayerPartner, patch: DosPrayerPartnerPatch) => Promise<LocalPrayerPartner>;
  onUpdatePrayerTeamCountVisibility: (value: boolean) => Promise<void>;
  onUpdatePrayerRequest: (id: string, patch: DosPrayerRequestPatch) => Promise<DosAppPrayerRequest>;
  people: DosAppPerson[];
  prayerPartners: DosAppPrayerPartner[];
  prayerRequests: DosAppPrayerRequest[];
  query: string;
  reminders: DosAppRelationshipReminder[];
  showPrayerTeamCount: boolean;
  tab: PrayerWorkspaceTab;
}) {
  const prayerReminders = reminders
    .filter((reminder) => reminder.reminderType === "prayer")
    .sort((first, second) => dateSortValue(nextReminderDate(first)) - dateSortValue(nextReminderDate(second)));
  const personById = new Map(people.map((person) => [person.id, person]));
  const meetingById = new Map(meetings.map((meeting) => [meeting.id, meeting]));
  const [prayingForView, setPrayingForView] = useState<PrayerRequestView>("praying");
  const [prayerRequestView, setPrayerRequestView] = useState<PrayerRequestView>("praying");
  const [isAddPrayerRequestOpen, setIsAddPrayerRequestOpen] = useState(false);
  const [isAddPrayerPartnerOpen, setIsAddPrayerPartnerOpen] = useState(false);
  const [isLogPrayerOpen, setIsLogPrayerOpen] = useState(false);
  const [isPrayerActionMenuOpen, setIsPrayerActionMenuOpen] = useState(false);
  const [deletedPrayerPartnerIds, setDeletedPrayerPartnerIds] = useState<string[]>([]);
  const [deletedPrayerRequestIds, setDeletedPrayerRequestIds] = useState<string[]>([]);
  const [localPrayerLogs, setLocalPrayerLogs] = useState<LocalPrayerLogEntry[]>([]);
  const [localPrayerPartners, setLocalPrayerPartners] = useState<LocalPrayerPartner[]>([]);
  const [localPrayerRequests, setLocalPrayerRequests] = useState<DosAppPrayerRequest[]>([]);
  const [selectedPrayerDetail, setSelectedPrayerDetail] = useState<PrayerDetail | null>(null);
  const [selectedPrayerPartner, setSelectedPrayerPartner] = useState<LocalPrayerPartner | null>(null);
  const [selectedPrayerRequest, setSelectedPrayerRequest] = useState<DosAppPrayerRequest | null>(null);
  const [prayerPlaceholder, setPrayerPlaceholder] = useState<{ description: string; title: string } | null>(null);
  const prayerSearch = query.trim().toLowerCase();
  const matchesPrayerSearch = (...values: Array<null | string | undefined>) => {
    if (!prayerSearch) {
      return true;
    }

    return values
      .filter(Boolean)
      .join(" ")
      .toLowerCase()
      .includes(prayerSearch);
  };
  const loadedPrayerPartnerRows = (prayerPartners ?? []).map(mapDosPrayerPartnerToLocal);
  const prayerPartnerRows = mergeRowsById(
    localPrayerPartners,
    loadedPrayerPartnerRows.length || localPrayerPartners.length ? loadedPrayerPartnerRows : [...desktopPrayerPartnerSamples],
  ).filter((partner) => !deletedPrayerPartnerIds.includes(partner.id));
  const mergedPrayerRequests = mergeRowsById(localPrayerRequests, prayerRequests ?? [])
    .filter((request) => !deletedPrayerRequestIds.includes(request.id));
  const prayerRequestById = new Map(mergedPrayerRequests.map((request) => [request.id, request]));
  const prayerRequestRows = mergedPrayerRequests.map(mapDosPrayerRequestToLocal);
  const visiblePrayerPartners = prayerPartnerRows.filter((partner) => (
    normalizePrayerPartnerStatus(partner.status) !== "archived"
    && matchesPrayerSearch(
      partner.name,
      partner.relationship,
      prayerPartnerTeamLabel(partner.prayerTeam, householdMembers),
      prayerPartnerHowJoinedLabel(partner.howHeard),
      partner.status,
      partner.lastContacted,
      partner.notes,
    )
  ));
  const visiblePrayerRequests = prayerRequestRows.filter((request) => (
    request.view === prayerRequestView
    && matchesPrayerSearch(request.request, request.category, request.sharedWith, request.status, request.created, request.answered)
  ));
  const prayingForRows: PrayerDetail[] = [
    ...localPrayerNeeds.map((item) => {
      const id = `local-${item.id}`;
      const meeting = meetingById.get(item.meetingId) ?? null;
      const latestPrayerLog = localPrayerLogs.find((log) => log.prayerId === id);

      return {
        createdAt: item.createdAt,
        frequency: "One time",
        id,
        kind: "reflection" as const,
        lastPrayedAt: latestPrayerLog?.prayedAt ?? null,
        meetingLabel: meeting ? `${meetingActivityTitle(meeting)} · ${formatDate(meeting.date)}` : "Linked table",
        meetingId: item.meetingId,
        notes: latestPrayerLog?.notes || null,
        personId: item.personId,
        personName: item.personName ?? "Leader Reflection",
        request: item.prayerNeeds,
        source: "Leader reflection",
        sourceId: item.id,
        status: "praying" as const,
      };
    }),
    ...leaderReflections
      .filter((reflection) => Boolean(normalizeText(reflection.prayerNeeds)))
      .map((reflection) => {
        const id = `reflection-${reflection.id}`;
        const person = personById.get(reflection.personId ?? "") ?? null;
        const meeting = meetingById.get(reflection.meetingId) ?? null;
        const meetingPersonName = meeting ? meetingPeopleTitle(meeting, people) : "";
        const latestPrayerLog = localPrayerLogs.find((log) => log.prayerId === id);

        return {
          createdAt: reflection.createdAt,
          frequency: "One time",
          id,
          kind: "reflection" as const,
          lastPrayedAt: latestPrayerLog?.prayedAt ?? null,
          meetingLabel: meeting ? `${meetingActivityTitle(meeting)} · ${formatDate(meeting.date)}` : "Linked table",
          meetingId: reflection.meetingId,
          notes: latestPrayerLog?.notes || (meeting ? `${meetingActivityTitle(meeting)} · ${formatDate(meeting.date)}` : null),
          personId: reflection.personId,
          personName: person?.name ?? (meetingPersonName || "Leader Reflection"),
          request: normalizeText(reflection.prayerNeeds),
          source: "Leader reflection",
          sourceId: reflection.id,
          status: "praying" as const,
        };
      }),
    ...prayerReminders.map((reminder) => {
      const id = `reminder-${reminder.id}`;
      const person = personById.get(reminder.personId) ?? null;
      const answeredAt = answeredPrayerByReminderId[reminder.id] ?? null;
      const latestPrayerLog = localPrayerLogs.find((log) => log.prayerId === id);

      return {
        answeredAt,
        createdAt: nextReminderDate(reminder),
        frequency: prayerFrequencyLabel(reminder.recurrence),
        id,
        kind: "reminder" as const,
        lastPrayedAt: latestPrayerLog?.prayedAt ?? null,
        meetingLabel: null,
        meetingId: null,
        notes: latestPrayerLog?.notes || reminderVisibleNotes(reminder.notes),
        personId: reminder.personId,
        personName: person?.name ?? "Unlinked person",
        request: reminderDisplayTitle(reminder, person),
        source: "Prayer reminder",
        sourceId: reminder.id,
        status: answeredAt ? "answered" as const : "praying" as const,
      };
    }),
  ];
  const visiblePrayingForRows = prayingForRows.filter((row) => (
    row.status === prayingForView
    && matchesPrayerSearch(
      row.personName,
      row.request,
      row.notes,
      row.source,
      row.frequency,
      row.status === "answered" ? "Answered" : "Praying",
      row.lastPrayedAt ? formatRelativeDate(row.lastPrayedAt) : undefined,
      row.answeredAt ? formatRelativeDate(row.answeredAt) : undefined,
      row.createdAt ? formatRelativeDate(row.createdAt) : undefined,
    )
  ));
  const markPrayerDetailPrayed = (detail: PrayerDetail, note: string) => {
    const prayedAt = new Date().toISOString();
    const entry: LocalPrayerLogEntry = {
      id: `local-prayer-log-${Date.now()}`,
      notes: note.trim(),
      prayedAt,
      prayerId: detail.id,
    };

    setLocalPrayerLogs((current) => [entry, ...current]);
    setSelectedPrayerDetail((current) => current?.id === detail.id ? { ...current, lastPrayedAt: prayedAt, notes: entry.notes || current.notes } : current);
  };
  const openPrayerPlaceholder = (title: string, description: string) => setPrayerPlaceholder({ description, title });
  const runPrayerAction = (action: () => void) => () => {
    setIsPrayerActionMenuOpen(false);
    action();
  };
  const prayerFloatingActionItems: MobileFloatingActionItem[] = [
    {
      icon: "prayer",
      label: "Add Prayer Request",
      onClick: runPrayerAction(() => setIsAddPrayerRequestOpen(true)),
    },
    {
      icon: "people",
      label: "Add Prayer Partner",
      onClick: runPrayerAction(() => setIsAddPrayerPartnerOpen(true)),
    },
  ];
  const showPrayerFloatingActions = !actionsHidden && !isAddPrayerRequestOpen && !isAddPrayerPartnerOpen && !isLogPrayerOpen && !prayerPlaceholder && !selectedPrayerDetail && !selectedPrayerPartner && !selectedPrayerRequest;

  useEffect(() => {
    setIsPrayerActionMenuOpen(false);
  }, [actionsHidden, isAddPrayerRequestOpen, isAddPrayerPartnerOpen, isLogPrayerOpen, prayerPlaceholder, selectedPrayerDetail, selectedPrayerPartner, selectedPrayerRequest, tab]);

  async function savePrayerRequestUpdate(id: string, patch: DosPrayerRequestPatch) {
    const savedRequest = await onUpdatePrayerRequest(id, patch);

    setLocalPrayerRequests((current) => upsertById(current, savedRequest));
    setSelectedPrayerRequest((current) => current?.id === savedRequest.id ? savedRequest : current);

    return savedRequest;
  }

  async function deletePrayerRequestFromWorkspace(id: string) {
    const deletedId = await onDeletePrayerRequest(id);

    setDeletedPrayerRequestIds((current) => current.includes(deletedId) ? current : [deletedId, ...current]);
    setLocalPrayerRequests((current) => current.filter((request) => request.id !== deletedId));
    setSelectedPrayerRequest(null);

    return deletedId;
  }

  async function savePrayerPartner(partner: LocalPrayerPartner, patch: DosPrayerPartnerPatch) {
    const savedPartner = await onUpdatePrayerPartner(partner, patch);

    setLocalPrayerPartners((current) => upsertById(current, savedPartner));
    setSelectedPrayerPartner((current) => current?.id === savedPartner.id ? savedPartner : current);

    return savedPartner;
  }

  async function deletePrayerPartnerFromWorkspace(partner: LocalPrayerPartner) {
    const deletedId = await onDeletePrayerPartner(partner);

    setDeletedPrayerPartnerIds((current) => current.includes(deletedId) ? current : [deletedId, ...current]);
    setLocalPrayerPartners((current) => current.filter((row) => row.id !== deletedId));
    setSelectedPrayerPartner(null);

    return deletedId;
  }

  return (
    <div className="hidden space-y-4 md:block">
      <DesktopSectionSearch
        ariaLabel="Search prayer"
        onChange={onSearchChange}
        placeholder="Search by person, request, partner, or meeting"
        query={query}
      />
      <SegmentedTabs onChange={onTabChange} options={prayerWorkspaceTabs} value={tab} />

      {tab === "partners" ? (
        <DesktopPanel
          compact
          eyebrow="Prayer Team"
        >
          <div className="mb-3 max-w-xl">
            <PrayerTeamCountVisibilityToggle checked={showPrayerTeamCount} onChange={onUpdatePrayerTeamCountVisibility} />
          </div>
            <DesktopPrayerTable
              columns={["Name", "Relationship Context", "Prayer Team", "Status", "Last Contacted"]}
              gridTemplateColumns="minmax(130px,1fr) minmax(120px,0.8fr) minmax(120px,0.8fr) 96px 110px"
              minWidth={0}
            >
              {visiblePrayerPartners.map((partner) => (
                <DesktopPrayerTableButtonRow
                  ariaLabel={`Open prayer partner ${partner.name}`}
                  gridTemplateColumns="minmax(130px,1fr) minmax(120px,0.8fr) minmax(120px,0.8fr) 96px 110px"
                  key={partner.id}
                  onClick={() => setSelectedPrayerPartner(partner)}
                >
                  <span className="truncate text-sm font-black text-[#0F172A]">{partner.name}</span>
                  <span className="truncate font-semibold text-[#475569]">{partner.relationship}</span>
                  <span className="truncate font-semibold text-[#475569]">{prayerPartnerTeamLabel(partner.prayerTeam, householdMembers)}</span>
                  <DesktopPrayerStatusPill>{partner.status}</DesktopPrayerStatusPill>
                  <span className="truncate font-semibold text-[#475569]">{partner.lastContacted}</span>
                </DesktopPrayerTableButtonRow>
              ))}
          </DesktopPrayerTable>
        </DesktopPanel>
      ) : null}

      {tab === "my_requests" ? (
        <DesktopPanel
          compact
          eyebrow="My Requests"
        >
          <div className="mb-3 max-w-xs">
            <SegmentedTabs onChange={setPrayerRequestView} options={prayerRequestViewTabs} value={prayerRequestView} />
          </div>
          <DesktopPrayerTable
            columns={["Request", "Category", "Shared With", "Status", "Created", "Answered", "Action"]}
            gridTemplateColumns="minmax(280px,1fr) 126px 150px 116px 104px 104px 110px"
            minWidth={990}
          >
            {visiblePrayerRequests.length ? visiblePrayerRequests.map((request) => (
              <DesktopPrayerTableButtonRow
                ariaLabel={`Open prayer request ${request.title}`}
                gridTemplateColumns="minmax(280px,1fr) 126px 150px 116px 104px 104px 110px"
                key={request.id}
                onClick={() => {
                  const selectedRequest = prayerRequestById.get(request.id);

                  if (selectedRequest) {
                    setSelectedPrayerRequest(selectedRequest);
                  }
                }}
              >
                <span className="truncate text-sm font-black text-[#0F172A]">{request.request}</span>
                <span className="truncate font-semibold text-[#475569]">{request.category}</span>
                <span className="truncate font-semibold text-[#475569]">{request.sharedWith}</span>
                <DesktopPrayerStatusPill>{request.status}</DesktopPrayerStatusPill>
                <span className="truncate font-semibold text-[#475569]">{request.created}</span>
                <span className="truncate font-semibold text-[#475569]">{request.answered}</span>
                <span className="justify-self-end rounded-full border border-[#DCEBFF] bg-white px-3 py-1.5 text-xs font-bold text-[#1D4ED8]">{request.action}</span>
              </DesktopPrayerTableButtonRow>
            )) : (
              <DesktopPrayerEmptyTableState
                action={<DesktopPrayerActionButton onClick={() => setIsAddPrayerRequestOpen(true)}>Add Request</DesktopPrayerActionButton>}
                text={prayerRequestView === "answered" ? "Answered requests will appear here." : "Add a prayer request to begin tracking it."}
                title={prayerRequestView === "answered" ? "No answered requests." : "No prayer requests."}
              />
            )}
          </DesktopPrayerTable>
        </DesktopPanel>
      ) : null}

      {tab === "praying_for" ? (
        <DesktopPanel
          compact
          eyebrow="Praying For"
        >
          <div className="mb-3 max-w-xs">
            <SegmentedTabs onChange={setPrayingForView} options={prayerRequestViewTabs} value={prayingForView} />
          </div>
          <DesktopPrayerTable
            columns={["Person", "Request", "Status", "Frequency", "Last Prayed", "Action"]}
            gridTemplateColumns="180px minmax(300px,1fr) 116px 126px 132px 110px"
            minWidth={920}
          >
            {visiblePrayingForRows.length ? (
              visiblePrayingForRows.map((row) => (
                <DesktopPrayerTableButtonRow
                  ariaLabel={`Open prayer detail for ${row.request}`}
                  key={row.id}
                  gridTemplateColumns="180px minmax(300px,1fr) 116px 126px 132px 110px"
                  onClick={() => setSelectedPrayerDetail(row)}
                >
                  <span className="truncate font-bold text-[#0F172A]">{row.personName}</span>
                  <span className="min-w-0">
                    <span className="block truncate text-sm font-black text-[#0F172A]">{row.request}</span>
                    <span className="mt-0.5 block truncate text-xs leading-5 text-[#64748B]">{row.source}</span>
                  </span>
                  <DesktopPrayerStatusPill>{row.status === "answered" ? "Answered" : "Praying"}</DesktopPrayerStatusPill>
                  <span className="truncate font-semibold text-[#475569]">{row.frequency}</span>
                  <span className="truncate font-semibold text-[#475569]">
                    {row.lastPrayedAt ? formatRelativeDate(row.lastPrayedAt) : row.answeredAt ? formatRelativeDate(row.answeredAt) : row.createdAt ? formatRelativeDate(row.createdAt) : "—"}
                  </span>
                  <span className="justify-self-end rounded-full border border-[#DCEBFF] bg-white px-3 py-1.5 text-xs font-bold text-[#1D4ED8]">View</span>
                </DesktopPrayerTableButtonRow>
              ))
            ) : (
              <DesktopPrayerEmptyTableState
                text={prayingForView === "answered" ? "Answered prayer will appear here after a request is marked answered." : "Prayer needs from logged tables and prayer reminders will appear here."}
                title={prayingForView === "answered" ? "No answered prayer yet." : "No prayer requests yet."}
              />
            )}
          </DesktopPrayerTable>
        </DesktopPanel>
      ) : null}

      {showPrayerFloatingActions ? (
        <MobileFloatingActions
          isOpen={isPrayerActionMenuOpen}
          items={prayerFloatingActionItems}
          onClose={() => setIsPrayerActionMenuOpen(false)}
          onToggle={() => setIsPrayerActionMenuOpen((current) => !current)}
          portalToBody
          variant="desktop"
        />
      ) : null}
      {isAddPrayerRequestOpen ? (
        <AddPrayerRequestSheet
          householdMembers={householdMembers}
          onClose={() => setIsAddPrayerRequestOpen(false)}
          onSubmit={async (draft) => {
            const savedRequest = await onCreatePrayerRequest(draft);
            setLocalPrayerRequests((current) => upsertById(current, savedRequest));
          }}
        />
      ) : null}
        {isAddPrayerPartnerOpen ? (
          <AddPrayerPartnerSheet
            householdMembers={householdMembers}
            onClose={() => setIsAddPrayerPartnerOpen(false)}
          onSubmit={async (partnerPatch) => {
            const savedPartner = await onCreatePrayerPartner(partnerPatch);
            setLocalPrayerPartners((current) => upsertById(current, savedPartner));

            if (savedPartner.notice) {
              setSelectedPrayerPartner(savedPartner);
            }

            return savedPartner;
          }}
        />
      ) : null}
      {isLogPrayerOpen ? (
        <LogPrayerSheet
          onClose={() => setIsLogPrayerOpen(false)}
          onSubmit={(entry) => {
            setLocalPrayerLogs((current) => [entry, ...current]);
            setIsLogPrayerOpen(false);
          }}
          prayerRows={prayingForRows.filter((row) => row.status === "praying")}
        />
      ) : null}
      {selectedPrayerDetail ? (
        <PrayerDetailSheet
          detail={selectedPrayerDetail}
          onClose={() => setSelectedPrayerDetail(null)}
          onMarkAnswered={onMarkPrayerAnswered}
          onMarkPrayed={markPrayerDetailPrayed}
          onOpenMeeting={onOpenMeeting}
          onOpenPerson={onOpenPerson}
        />
      ) : null}
      {selectedPrayerRequest ? (
        <PrayerRequestDetailSheet
          householdMembers={householdMembers}
          onClose={() => setSelectedPrayerRequest(null)}
          onDelete={deletePrayerRequestFromWorkspace}
          onSave={savePrayerRequestUpdate}
          request={selectedPrayerRequest}
        />
      ) : null}
        {selectedPrayerPartner ? (
          <PrayerPartnerDetailSheet
            householdMembers={householdMembers}
            onClose={() => setSelectedPrayerPartner(null)}
          onDeletePartner={deletePrayerPartnerFromWorkspace}
          onSavePartner={savePrayerPartner}
          partner={selectedPrayerPartner}
        />
      ) : null}
      {prayerPlaceholder ? (
        <DesktopPrayerPlaceholderSheet
          description={prayerPlaceholder.description}
          onClose={() => setPrayerPlaceholder(null)}
          title={prayerPlaceholder.title}
        />
      ) : null}
    </div>
  );
}

function PeopleImportSheet({
  existingPeople,
  onClose,
  onImport,
}: {
  existingPeople: DosAppPerson[];
  onClose: () => void;
  onImport: (rows: PeopleImportRow[]) => Promise<PeopleImportResult>;
}) {
  const [fileName, setFileName] = useState("");
  const [importError, setImportError] = useState("");
  const [importResult, setImportResult] = useState<PeopleImportResult | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [parseError, setParseError] = useState("");
  const [rows, setRows] = useState<PeopleImportRow[]>([]);
  const analysis = useMemo(() => analyzePeopleImportRows(rows, existingPeople), [existingPeople, rows]);
  const previewRows = rows.slice(0, 5);
  const canImport = analysis.readyRows.length > 0 && !isImporting;

  async function handleFileChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];

    setFileName(file?.name ?? "");
    setImportError("");
    setImportResult(null);
    setParseError("");
    setRows([]);

    if (!file) {
      return;
    }

    if (!file.name.toLowerCase().endsWith(".csv")) {
      setParseError("Choose a CSV file.");
      return;
    }

    try {
      const text = await file.text();
      const parsedCsv = parseCsvText(text);

      if (!parsedCsv.headers.length || !parsedCsv.rows.length) {
        setParseError("This CSV needs a header row and at least one contact.");
        return;
      }

      setRows(parsedCsv.rows.map((row, index) => mapDosPeopleCsvRow(parsedCsv.headers, row, index)));
    } catch (error) {
      setParseError(error instanceof Error ? error.message : "Unable to read this CSV.");
    }
  }

  async function handleImport() {
    if (!canImport) {
      return;
    }

    setImportError("");
    setImportResult(null);
    setIsImporting(true);

    try {
      const result = await onImport(analysis.readyRows);

      setImportResult(result);
    } catch (error) {
      setImportError(error instanceof Error ? error.message : "Unable to import contacts.");
    } finally {
      setIsImporting(false);
    }
  }

  return (
    <Sheet description="Upload a CSV to add people to your field." onClose={onClose} title="Import Contacts">
      <div className="space-y-4">
        <label className="block rounded-[22px] border border-dashed border-[#BFDBFE] bg-white p-4">
          <FieldLabel>CSV File</FieldLabel>
          <input
            accept=".csv,text/csv"
            className="mt-3 block w-full text-sm text-[#64748B] file:mr-4 file:rounded-full file:border-0 file:bg-[#2563EB] file:px-4 file:py-2 file:text-sm file:font-semibold file:text-white"
            onChange={handleFileChange}
            type="file"
          />
          {fileName ? <p className="mt-3 text-xs text-[#64748B]">Loaded {fileName}</p> : null}
        </label>

        {parseError ? <p className="rounded-2xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{parseError}</p> : null}
        {importError ? <p className="rounded-2xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{importError}</p> : null}
        {importResult ? (
          <p className="rounded-2xl border border-[#BFDBFE] bg-[#EBF2FF] p-3 text-sm text-[#1D4ED8]">
            Imported {importResult.importedCount}. Skipped {importResult.skippedCount}.
          </p>
        ) : null}

        {rows.length ? (
          <div className="rounded-[22px] border border-[#E2E8F0] bg-white p-4">
            <div className="grid grid-cols-3 gap-2 text-center">
              <SummaryTile label="Ready" value={String(analysis.readyRows.length)} />
              <SummaryTile label="Duplicates" value={String(analysis.duplicateRows.length)} />
              <SummaryTile label="Needs Name" value={String(analysis.invalidRows.length)} />
            </div>
            <div className="mt-4 space-y-2">
              {previewRows.map((row) => (
                <div className="rounded-2xl bg-[#F1F5F9] p-3" key={`${row.sourceRowNumber}-${row.name}-${row.phone}`}>
                  <p className="text-sm font-bold text-[#0F172A]">{row.name || "Missing name"}</p>
                  <p className="mt-1 text-xs leading-5 text-[#64748B]">
                    {[formatPhoneNumber(row.phone) || row.phone, row.email, row.church, row.spouseName ? `Spouse: ${row.spouseName}` : ""].filter(Boolean).join(" · ") || `Row ${row.sourceRowNumber}`}
                  </p>
                </div>
              ))}
            </div>
          </div>
        ) : null}

        <AppButton disabled={!canImport} icon="add" onClick={handleImport} tone="black">
          {isImporting ? "Importing..." : analysis.readyRows.length ? `Import ${analysis.readyRows.length} Contacts` : "Import Contacts"}
        </AppButton>
      </div>
    </Sheet>
  );
}

function RelationshipTypePicker({
  onChange,
  value,
}: {
  onChange: (value: DosRelationshipModel) => void;
  value: DosRelationshipModel;
}) {
  const selectedValue = relationshipTypeFromModel(value);

  return (
    <fieldset>
      <legend className="sr-only">Relationship Type</legend>
      <div className="grid grid-cols-2 gap-2">
        {relationshipTypeOptions.map((option) => {
          const selected = selectedValue === option.value;

          return (
            <label
              className={`relative flex min-h-12 cursor-pointer items-center rounded-2xl border px-3 py-2 transition-colors ${
                selected
                  ? "border-[#2563EB] bg-[#EBF2FF] shadow-[0_8px_20px_rgba(37,99,235,0.08)]"
                  : "border-[#E2E8F0] bg-white hover:border-[#BFDBFE]"
              }`}
              key={option.value}
            >
              <input
                checked={selected}
                className="absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0"
                name="relationship_type"
                onChange={() => onChange(relationshipModelFromRelationshipType(option.value as RelationshipTypeValue, value))}
                required
                type="radio"
                value={option.value}
              />
              <span className="pr-6 text-[13px] font-bold leading-tight text-[#0F172A]">{option.label}</span>
              <span
                className={`absolute right-3 top-1/2 flex h-4 w-4 -translate-y-1/2 items-center justify-center rounded-full border transition-colors ${
                  selected ? "border-[#2563EB] bg-white" : "border-[#CBD5E1] bg-white"
                }`}
                aria-hidden="true"
              >
                {selected ? <span className="h-2 w-2 rounded-full bg-[#2563EB]" /> : null}
              </span>
            </label>
          );
        })}
      </div>
    </fieldset>
  );
}

function RelationshipContextPicker({
  onChange,
  value,
}: {
  onChange: (value: DosRelationshipModel) => void;
  value: DosRelationshipModel;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const selectedOption = relationshipContextOptions.find((option) => option.value === value.relationshipContext) ?? relationshipContextOptions[relationshipContextOptions.length - 1];

  return (
    <fieldset className="overflow-hidden rounded-[18px] border border-[#E2E8F0] bg-white">
      <legend className="sr-only">Relationship Context</legend>
      <button
        aria-expanded={isOpen}
        className="flex min-h-[56px] w-full items-center justify-between gap-3 px-4 py-3 text-left transition-colors hover:bg-[#F8FAFC] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#2563EB]/25"
        onClick={() => setIsOpen((current) => !current)}
        type="button"
      >
        <span className="min-w-0">
          <span className="block truncate text-sm font-bold text-[#0F172A]">{selectedOption.label}</span>
        </span>
        <ChevronRight
          className={`h-4 w-4 shrink-0 text-[#94A3B8] transition-transform ${isOpen ? "-rotate-90" : "rotate-90"}`}
          aria-hidden="true"
          strokeWidth={1.9}
        />
      </button>
      {isOpen ? (
        <div className="grid grid-cols-2 gap-2 border-t border-[#E2E8F0] bg-[#F8FAFC] p-2">
          {relationshipContextOptions.map((option) => {
            const selected = value.relationshipContext === option.value;

            return (
              <button
                className={`relative flex min-h-10 items-center justify-between gap-2 rounded-2xl border px-3 text-left text-xs font-bold transition-colors ${
                  selected
                    ? "border-[#2563EB] bg-[#EBF2FF] text-[#1D4ED8]"
                    : "border-[#E2E8F0] bg-white text-[#475569] hover:border-[#BFDBFE]"
                }`}
                key={option.value}
                onClick={() => {
                  onChange({ ...value, relationshipContext: option.value });
                  setIsOpen(false);
                }}
                type="button"
              >
                <span className="min-w-0 truncate">{option.label}</span>
                <span
                  className={`flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-full border transition-colors ${
                    selected ? "border-[#2563EB] bg-white" : "border-[#CBD5E1] bg-white"
                  }`}
                  aria-hidden="true"
                >
                  {selected ? <span className="h-1.5 w-1.5 rounded-full bg-[#2563EB]" /> : null}
                </span>
              </button>
            );
          })}
        </div>
      ) : null}
    </fieldset>
  );
}

function RelationshipScorePicker({
  onChange,
  value,
}: {
  onChange: (value: RelationshipScoreValue) => void;
  value: RelationshipScoreValue;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const selectedOption = commitmentLevelOptions.find((option) => option.value === value) ?? commitmentLevelOptions.find((option) => option.value === 0)!;

  return (
    <fieldset>
      <legend className="sr-only">Engagement Level</legend>
      <input name="engagement_score" type="hidden" value={relationshipScoreLabel(value)} />
      <div className="relative">
        <button
          aria-expanded={isOpen}
          className="flex min-h-[56px] w-full items-center justify-between gap-3 rounded-[18px] border border-[#E2E8F0] bg-white px-4 py-3 text-left transition-colors hover:border-[#BFDBFE] hover:bg-[#F8FAFC] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#2563EB]/25"
          onClick={() => setIsOpen((current) => !current)}
          type="button"
        >
          <span className="min-w-0">
            <span className="block truncate text-sm font-bold text-[#0F172A]">{selectedOption.label}</span>
          </span>
          <ChevronRight
            className={`h-4 w-4 shrink-0 text-[#94A3B8] transition-transform ${isOpen ? "-rotate-90" : "rotate-90"}`}
            aria-hidden="true"
            strokeWidth={1.9}
          />
        </button>

        {isOpen ? (
          <div className="absolute left-0 right-0 z-30 mt-2 max-h-[280px] overflow-y-auto rounded-[20px] border border-[#E2E8F0] bg-white p-2 shadow-[0_18px_48px_rgba(15,23,42,0.16)]">
            {commitmentLevelOptions.map((option) => {
              const selected = value === option.value;

              return (
                <button
                  className={`flex w-full items-start gap-3 rounded-2xl px-3 py-2.5 text-left transition-colors ${
                    selected
                      ? "bg-[#EBF2FF] text-[#0F172A]"
                      : "text-[#475569] hover:bg-[#F8FAFC]"
                  }`}
                  key={option.value}
                  onClick={() => {
                    onChange(option.value);
                    setIsOpen(false);
                  }}
                  type="button"
                >
                  <span
                    className={`mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full border transition-colors ${
                      selected ? "border-[#2563EB] bg-white" : "border-[#CBD5E1] bg-white"
                    }`}
                    aria-hidden="true"
                  >
                    {selected ? <span className="h-2 w-2 rounded-full bg-[#2563EB]" /> : null}
                  </span>
                  <span className="min-w-0">
                    <span className={`block text-sm font-bold leading-tight ${selected ? "text-[#1D4ED8]" : "text-[#0F172A]"}`}>{option.label}</span>
                    <span className="mt-1 block text-[11px] leading-4 text-[#64748B]">{option.helper}</span>
                  </span>
                </button>
              );
            })}
          </div>
        ) : null}
      </div>
    </fieldset>
  );
}

function AdditionalPersonInformation({
  defaults = {},
  householdDraft,
  onHouseholdDraftChange,
  isOpen,
  onToggle,
  showToggle = true,
}: {
  defaults?: PersonFormDefaults;
  householdDraft: PersonHouseholdDraft;
  onHouseholdDraftChange: (value: PersonHouseholdDraft) => void;
  isOpen: boolean;
  onToggle: () => void;
  showToggle?: boolean;
}) {
  const updateSpouseDraft = (key: "spouseFirstName" | "spouseLastName", value: string) => {
    onHouseholdDraftChange({
      ...householdDraft,
      [key]: value,
    });
  };

  const updateChildDraft = (childId: string, key: "firstName" | "lastName", value: string) => {
    onHouseholdDraftChange({
      ...householdDraft,
      children: householdDraft.children.map((child) => (
        child.id === childId ? { ...child, [key]: value } : child
      )),
    });
  };

  const addChildDraft = () => {
    onHouseholdDraftChange({
      ...householdDraft,
      children: [
        ...householdDraft.children,
        {
          firstName: "",
          id: `child-${Date.now()}-${householdDraft.children.length}`,
          lastName: "",
        },
      ],
    });
  };

  const removeChildDraft = (childId: string) => {
    const remainingChildren = householdDraft.children.filter((child) => child.id !== childId);

    onHouseholdDraftChange({
      ...householdDraft,
      children: remainingChildren.length ? remainingChildren : [blankChildDraft()],
    });
  };

  const fields = (
    <div className={showToggle ? "mt-5 grid gap-5 border-t border-[#EAF2FF] pt-5" : "grid gap-5"}>
      <DosFormSection icon="people" title="Contact Information">
        <DosFormField label="Email">
          <input className={FieldInputClass()} defaultValue={defaults.email} name="email" placeholder="email@example.com" type="email" />
        </DosFormField>
        <DosFormField label="Home Address">
          <input className={FieldInputClass()} defaultValue={defaults.homeAddress} name="home_address" placeholder="Street address" />
        </DosFormField>
        <div className="grid gap-3 min-[420px]:grid-cols-[minmax(0,1fr)_72px_86px]">
          <DosFormField label="City">
            <input className={FieldInputClass()} defaultValue={defaults.city} name="city" />
          </DosFormField>
          <DosFormField label="State">
            <input className={FieldInputClass()} defaultValue={defaults.state} maxLength={2} name="state" />
          </DosFormField>
          <DosFormField label="ZIP">
            <input className={FieldInputClass()} defaultValue={defaults.zip} inputMode="numeric" name="zip" />
          </DosFormField>
        </div>
        <DosFormGrid>
          <DosFormField label="Church">
            <input className={FieldInputClass()} defaultValue={defaults.church} name="church" placeholder="Church / community" />
          </DosFormField>
          <DosFormField label="Occupation">
            <input className={FieldInputClass()} defaultValue={defaults.occupation} name="occupation" placeholder="What do they do?" />
          </DosFormField>
        </DosFormGrid>
        <DosDateInput autoComplete="bday" defaultValue={defaults.birthday} label="Birthday" maxYear={new Date().getFullYear()} name="birthday" />
      </DosFormSection>
      <DosFormSection icon="home" title="Household Information">
        <details className="group overflow-hidden rounded-[20px] border border-[#D6E4F7] bg-white">
          <summary className="flex min-h-[52px] cursor-pointer list-none items-center justify-between gap-3 px-4 py-3 text-left transition-colors hover:bg-[#F8FBFF] [&::-webkit-details-marker]:hidden">
            <span>
              <span className="block text-sm font-bold text-[#0F172A]">Show household fields</span>
              <span className="mt-1 block text-xs font-semibold leading-5 text-[#64748B]">Household names are kept selectable for tables.</span>
            </span>
            <ChevronRight className="h-4 w-4 shrink-0 rotate-90 text-[#94A3B8] transition-transform group-open:-rotate-90" aria-hidden="true" strokeWidth={1.9} />
          </summary>
          <div className="grid gap-3 border-t border-[#EAF2FF] bg-white p-3">
            <DosFormGrid>
              <DosFormField label="Spouse First Name">
                <input className={FieldInputClass()} onChange={(event) => updateSpouseDraft("spouseFirstName", event.target.value)} value={householdDraft.spouseFirstName} />
              </DosFormField>
              <DosFormField label="Spouse Last Name">
                <input className={FieldInputClass()} onChange={(event) => updateSpouseDraft("spouseLastName", event.target.value)} value={householdDraft.spouseLastName} />
              </DosFormField>
            </DosFormGrid>
            <DosDateInput defaultValue={defaults.anniversaryDate} label="Anniversary Date" name="anniversary_date" />
            <div className="grid gap-2">
              <div className="flex items-center justify-between gap-3">
                <FieldLabel>Children</FieldLabel>
                <button
                  className="inline-flex h-8 items-center rounded-full border border-[#BFDBFE] bg-white px-3 text-xs font-bold text-[#2563EB] transition-colors hover:bg-[#EBF2FF]"
                  onClick={addChildDraft}
                  type="button"
                >
                  + Child
                </button>
              </div>
              <div className="grid gap-2">
                {householdDraft.children.map((child, index) => (
                  <div className="grid gap-2 rounded-[18px] border border-[#D6E4F7] bg-white p-2" key={child.id}>
                    <div className="grid gap-2 min-[420px]:grid-cols-[minmax(0,1fr)_minmax(0,1fr)_32px]">
                      <DosFormField label="Child First Name">
                        <input className={FieldInputClass()} onChange={(event) => updateChildDraft(child.id, "firstName", event.target.value)} value={child.firstName} />
                      </DosFormField>
                      <DosFormField label="Child Last Name">
                        <input className={FieldInputClass()} onChange={(event) => updateChildDraft(child.id, "lastName", event.target.value)} value={child.lastName} />
                      </DosFormField>
                      <button
                        aria-label={`Remove child ${index + 1}`}
                        className="mt-0 flex h-9 w-9 items-center justify-center justify-self-end rounded-full border border-[#E2E8F0] bg-white text-[#64748B] transition-colors hover:border-red-200 hover:bg-red-50 hover:text-red-600 min-[420px]:mt-5"
                        onClick={() => removeChildDraft(child.id)}
                        type="button"
                      >
                        <X className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </details>
      </DosFormSection>
      <DosFormSection icon="bell" title="Important Dates & Reminders">
        <ImportantDatesReminderSection />
      </DosFormSection>
      <DosFormSection icon="log" title="Notes">
        <DosFormField>
          <VoiceTextarea aria-label="Notes" className={FieldTextareaClass(false)} defaultValue={defaults.notes} name="notes" />
        </DosFormField>
      </DosFormSection>
    </div>
  );

  if (!showToggle) {
    return (
      <section className="grid gap-2">
        {fields}
      </section>
    );
  }

  return (
    <section className="rounded-[20px] border border-[#D6E4F7] bg-white p-4">
      <button
        aria-expanded={isOpen}
        className="flex w-full items-center justify-between gap-3 text-left"
        onClick={onToggle}
        type="button"
      >
        <span>
          <span className="block text-sm font-bold text-[#0F172A]">Additional Information</span>
        </span>
        <span className={`text-lg leading-none text-[#94A3B8] transition-transform ${isOpen ? "rotate-45" : ""}`} aria-hidden="true">
          +
        </span>
      </button>

      {isOpen ? fields : null}
    </section>
  );
}

function ImportantDatesReminderSection() {
  const [tag, setTag] = useState<ImportantReminderTag>("prayer");
  const [repeat, setRepeat] = useState<ImportantReminderRepeat>(importantReminderRepeatForTag("prayer"));
  const [timing, setTiming] = useState<ImportantReminderTiming>("day_of");
  const [destination, setDestination] = useState<ImportantReminderDestination>(importantReminderDestinationForTag("prayer"));
  const [showOnDashboard, setShowOnDashboard] = useState(true);

  function handleTagChange(nextValue: string) {
    const nextTag = normalizeImportantReminderTag(nextValue);

    setTag(nextTag);
    setRepeat(importantReminderRepeatForTag(nextTag));
    setDestination(importantReminderDestinationForTag(nextTag));
  }

  return (
    <details className="group rounded-[20px] border border-[#D6E4F7] bg-white">
      <summary className="flex min-h-[52px] cursor-pointer list-none items-center justify-between gap-3 px-4 py-3 text-left transition-colors hover:bg-[#F8FBFF] [&::-webkit-details-marker]:hidden">
        <span>
          <span className="block text-sm font-bold text-[#0F172A]">Add a reminder</span>
          <span className="mt-1 block text-xs font-semibold leading-5 text-[#64748B]">Add one dated reminder to this person.</span>
        </span>
        <ChevronRight className="h-4 w-4 shrink-0 rotate-90 text-[#94A3B8] transition-transform group-open:-rotate-90" aria-hidden="true" strokeWidth={1.9} />
      </summary>
      <div className="grid gap-3 border-t border-[#EAF2FF] bg-white p-3">
        <input name="important_reminder_tag" type="hidden" value={tag} />
        <input name="important_reminder_repeats" type="hidden" value={repeat} />
        <input name="important_reminder_timing" type="hidden" value={timing} />
        <input name="important_reminder_destination" type="hidden" value={destination} />
        <DosFormField label="Title">
          <input className={FieldInputClass()} name="important_reminder_title" placeholder="Surgery, birthday text, memorial date..." />
        </DosFormField>
        <div className="grid gap-3 min-[380px]:grid-cols-2">
          <CompactOptionSelect label="Tag" onChange={handleTagChange} options={importantReminderTagOptions} value={tag} />
          <DosDateInput label="Date" name="important_reminder_date" />
        </div>
        <div className="grid gap-3 min-[380px]:grid-cols-2">
          <CompactOptionSelect label="Repeats" onChange={(value) => setRepeat(value as ImportantReminderRepeat)} options={importantReminderRepeatOptions} value={repeat} />
          <CompactOptionSelect label="Reminder timing" onChange={(value) => setTiming(normalizeImportantReminderTiming(value))} options={importantReminderTimingOptions} value={timing} />
        </div>
        <DosFormToggleRow
          checked={showOnDashboard}
          description="Eligible for Upcoming and notifications."
          name="important_reminder_show_dashboard"
          onChange={(event) => setShowOnDashboard(event.target.checked)}
          title="Show on Dashboard"
        />
        <CompactOptionSelect label="Send to app" onChange={(value) => setDestination(normalizeImportantReminderDestination(value))} options={importantReminderDestinationOptions} value={destination} />
        <DosFormField label="Notes">
          <VoiceTextarea className={`${FieldTextareaClass()} min-h-20`} name="important_reminder_notes" placeholder="Context for the reminder." />
        </DosFormField>
      </div>
    </details>
  );
}

function PersonExtraDetails({
  additionalDefaults,
  detailsOpen,
  householdDraft,
  onHouseholdDraftChange,
  onToggleDetails,
  showToggle = true,
}: {
  additionalDefaults?: PersonFormDefaults;
  detailsOpen: boolean;
  householdDraft: PersonHouseholdDraft;
  onHouseholdDraftChange: (value: PersonHouseholdDraft) => void;
  onToggleDetails: () => void;
  showToggle?: boolean;
}) {
  const fields = (
    <AdditionalPersonInformation
      defaults={additionalDefaults}
      householdDraft={householdDraft}
      isOpen
      onHouseholdDraftChange={onHouseholdDraftChange}
      onToggle={onToggleDetails}
      showToggle={false}
    />
  );

  if (!showToggle) {
    return <section>{fields}</section>;
  }

  return (
    <section className="space-y-3">
      <button
        aria-expanded={detailsOpen}
        className="flex w-full items-center justify-between rounded-[18px] border border-[#D6E4F7] bg-white px-4 py-3 text-left text-sm font-semibold text-[#2563EB] transition-colors hover:border-[#BFDBFE] hover:bg-[#F8FBFF]"
        onClick={onToggleDetails}
        type="button"
      >
        <span>{detailsOpen ? "Hide Extra Details" : "Show Extra Details"}</span>
        <span className={`text-lg leading-none text-[#94A3B8] transition-transform ${detailsOpen ? "rotate-45" : ""}`} aria-hidden="true">
          +
        </span>
      </button>
      {detailsOpen ? fields : null}
    </section>
  );
}

function PersonFormContent({
  additionalDefaults,
  buttonText,
  detailsOpen,
  errorMessage,
  isSubmitting,
  nameDefault,
  onRelationshipChange,
  onDelete,
  onScoreChange,
  onSubmit,
  onToggleDetails,
  phoneDefault,
  relationshipModel,
  scoreValue,
  showDetailsToggle = true,
  submittingText,
}: {
  additionalDefaults?: PersonFormDefaults;
  buttonText: string;
  detailsOpen: boolean;
  errorMessage: string;
  isSubmitting: boolean;
  nameDefault?: string | null;
  onRelationshipChange: (value: DosRelationshipModel) => void;
  onDelete?: () => void;
  onScoreChange: (value: RelationshipScoreValue) => void;
  onSubmit: (event: FormEvent<HTMLFormElement>) => void;
  onToggleDetails: () => void;
  phoneDefault?: string | null;
  relationshipModel: DosRelationshipModel;
  scoreValue: RelationshipScoreValue;
  showDetailsToggle?: boolean;
  submittingText: string;
}) {
  const [nameDraft, setNameDraft] = useState(() => splitNameParts(nameDefault));
  const [phoneDraft, setPhoneDraft] = useState(() => phoneDigitsOnly(phoneDefault));
  const [householdDraft, setHouseholdDraft] = useState<PersonHouseholdDraft>(() => householdDraftFromDefaults(additionalDefaults));

  useEffect(() => {
    setNameDraft(splitNameParts(nameDefault));
  }, [nameDefault]);

  useEffect(() => {
    setPhoneDraft(phoneDigitsOnly(phoneDefault));
  }, [phoneDefault]);

  useEffect(() => {
    setHouseholdDraft(householdDraftFromDefaults(additionalDefaults));
  }, [additionalDefaults?.childrenNames, additionalDefaults?.spouseName]);

  const composedName = joinNameParts(nameDraft.firstName, nameDraft.lastName);
  const effectiveDetailsOpen = showDetailsToggle ? detailsOpen : true;

  return (
    <form className="space-y-5" onSubmit={onSubmit}>
      <input name="name" type="hidden" value={composedName} />
      <input name="phone" type="hidden" value={phoneDraft} />
      <input name="spouse_name" type="hidden" value={householdDraftSpouseName(householdDraft)} />
      <input name="children_names" type="hidden" value={householdDraftChildrenNames(householdDraft)} />
      <DosFormSection icon="people" title="Person">
        <DosFormGrid>
          <DosFormField label="First Name">
            <input className={FieldInputClass()} onChange={(event) => setNameDraft((current) => ({ ...current, firstName: event.target.value }))} required value={nameDraft.firstName} />
          </DosFormField>
          <DosFormField label="Last Name">
            <input className={FieldInputClass()} onChange={(event) => setNameDraft((current) => ({ ...current, lastName: event.target.value }))} value={nameDraft.lastName} />
          </DosFormField>
        </DosFormGrid>
        <DosFormField label="Phone">
          <input
            className={FieldInputClass()}
            inputMode="tel"
            onChange={(event) => setPhoneDraft(phoneDigitsOnly(event.target.value))}
            placeholder="(651) 456-8974"
            required
            type="tel"
            value={formatPhoneNumber(phoneDraft)}
          />
        </DosFormField>
      </DosFormSection>
      <DosFormSection icon="people" title="Field Visibility">
        <FormOptionSelect
          defaultValue={additionalDefaults?.fieldVisibility ?? "primary"}
          label="Discipleship Role"
          name="field_visibility"
          options={fieldVisibilityOptions}
        />
      </DosFormSection>
      <DosFormSection icon="people" title="Relationship Type">
        <RelationshipTypePicker onChange={onRelationshipChange} value={relationshipModel} />
      </DosFormSection>
      <DosFormSection icon="people" title="Relationship Context">
        <RelationshipContextPicker onChange={onRelationshipChange} value={relationshipModel} />
      </DosFormSection>
      <DosFormSection icon="people" title="Discipleship Relationship">
        <FormOptionSelect
          defaultValue={additionalDefaults?.discipleshipRelationship ?? ""}
          label="Context"
          name="discipleship_relationship"
          options={discipleshipRelationshipOptions}
        />
      </DosFormSection>
      <DosFormSection icon="fruit" title="Engagement Level">
        <RelationshipScorePicker onChange={onScoreChange} value={scoreValue} />
      </DosFormSection>
      <PersonExtraDetails
        additionalDefaults={additionalDefaults}
        detailsOpen={effectiveDetailsOpen}
        householdDraft={householdDraft}
        onHouseholdDraftChange={setHouseholdDraft}
        onToggleDetails={onToggleDetails}
        showToggle={showDetailsToggle}
      />
      {errorMessage ? <p className="rounded-2xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{errorMessage}</p> : null}
      <AppButton disabled={isSubmitting} tone="black" type="submit">{isSubmitting ? submittingText : buttonText}</AppButton>
      {onDelete ? (
        <button
          className="mt-2 w-full rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-bold text-red-700 transition-colors hover:border-red-300 hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-60"
          disabled={isSubmitting}
          onClick={onDelete}
          type="button"
        >
          Delete Person
        </button>
      ) : null}
    </form>
  );
}

function DetailCard({
  children,
  icon,
  title,
}: {
  children: ReactNode;
  icon?: ReactNode;
  title: string;
}) {
  return (
    <section className="min-w-0 overflow-hidden rounded-[24px] border border-[#E2E8F0] bg-white p-4 shadow-[0_14px_34px_rgba(37,99,235,0.055)]">
      <div className="flex items-center gap-2">
        {icon ? (
          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[#EBF2FF] text-[#2563EB]">
            {icon}
          </span>
        ) : null}
        <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
          {title}
        </p>
      </div>
      <div className="mt-3 grid min-w-0 grid-cols-1 gap-3">{children}</div>
    </section>
  );
}

function SectionEmptyState({
  action,
  text,
  title,
}: {
  action?: ReactNode;
  text?: string;
  title: string;
}) {
  return (
    <div className="flex min-w-0 gap-3 rounded-[20px] border border-[#DCEBFF] bg-[#F8FAFC] p-3.5 shadow-[0_8px_22px_rgba(37,99,235,0.035)]">
      <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#EBF2FF] text-[#2563EB] ring-1 ring-[#BFDBFE]">
        <Sparkles className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-sm font-bold leading-5 text-[#0F172A]">{title}</span>
        {text ? <span className="mt-1 block text-sm leading-6 text-[#64748B]">{text}</span> : null}
        {action ? <span className="mt-3 block">{action}</span> : null}
      </span>
    </div>
  );
}

const myRecordJournalTags = ["Prayer", "Scripture", "Worship", "Repentance", "Direction", "Thanksgiving"] as const;
