  async function createPrayerPartner(patch: DosPrayerPartnerPatch) {
    const normalizedStatus = normalizePrayerPartnerStatus(patch.status ?? "pending");

    setErrorMessage("");

    if (isPreview) {
      throw new Error("Preview mode is read-only. Demo changes are not saved.");
    }

    setIsSubmitting(true);

    try {
      const response = await fetch("/api/dos/app/prayer-partners", {
        body: JSON.stringify({
          ...patch,
          status: normalizedStatus,
          workspaceId: data.workspace.id,
        }),
        headers: {
          "Content-Type": "application/json",
        },
        method: "POST",
      });
      const result = await response.json().catch(() => ({})) as {
        duplicate?: boolean;
        error?: string;
        message?: string;
        prayerPartner?: DosAppPrayerPartner;
      };

      if (!response.ok || !result.prayerPartner) {
        throw new Error(result.error ?? "Unable to save prayer partner.");
      }

      router.refresh();

      const savedPartner = mapDosPrayerPartnerToLocal(result.prayerPartner);

      return result.duplicate
        ? { ...savedPartner, notice: result.message ?? prayerPartnerDuplicateMessage }
        : savedPartner;
    } catch (error) {
      const rawMessage = error instanceof Error ? error.message : "Unable to save prayer partner.";
      const message = rawMessage.includes("duplicate key") || rawMessage.includes("unique constraint")
        ? prayerPartnerDuplicateMessage
        : rawMessage;

      setErrorMessage(message);
      throw new Error(message);
    } finally {
      setIsSubmitting(false);
    }
  }

