  function personAnniversaryReminderRequest(formData: FormData, personId: string) {
    const anniversaryDate = String(formData.get("anniversary_date") ?? "").trim();

    if (!anniversaryDate) {
      return null;
    }

    const existingAnniversary = data.reminders.find((reminder) => reminder.personId === personId && reminder.reminderType === "anniversary");

    return {
      method: existingAnniversary ? "PATCH" as const : "POST" as const,
      payload: {
        googleSyncEnabled: false,
        google_sync_enabled: false,
        id: existingAnniversary?.id,
        notes: "Household anniversary",
        personId,
        person_id: personId,
        recurrence: "yearly",
        reminderDate: anniversaryDate,
        reminder_date: anniversaryDate,
        reminderType: "anniversary",
        reminder_type: "anniversary",
        title: "Anniversary",
      },
    };
  }

  function importantDateReminderRequest(formData: FormData, personId: string) {
    const reminderDate = String(formData.get("important_reminder_date") ?? "").trim();

    if (!reminderDate) {
      return null;
    }

    const tag = normalizeImportantReminderTag(formData.get("important_reminder_tag"));
    const timing = normalizeImportantReminderTiming(formData.get("important_reminder_timing"));
    const destination = normalizeImportantReminderDestination(formData.get("important_reminder_destination"));
    const repeatValue = String(formData.get("important_reminder_repeats") ?? importantReminderRepeatForTag(tag));
    const recurrence: ImportantReminderRepeat = repeatValue === "yearly" || importantReminderRepeatForTag(tag) === "yearly" ? "yearly" : "none";
    const showOnDashboard = formData.get("important_reminder_show_dashboard") === "on";
    const title = String(formData.get("important_reminder_title") ?? "").trim();
    const tagLabel = importantReminderTagLabel(tag);
    const reminderType = destination === "prayer" || tag === "prayer" ? "prayer" : reminderTypeForImportantTag(tag);
    const defaultTitle = tag === "prayer" ? "Prayer" : tag === "anniversary" ? "Anniversary" : tagLabel;
    const visibleTitle = title || defaultTitle;
    const notes = String(formData.get("important_reminder_notes") ?? "");
    const meta: ImportantReminderMeta = {
      destination,
      showOnDashboard,
      tag,
      timing,
    };

    return {
      method: "POST" as const,
      payload: {
        googleSyncEnabled: destination === "calendar" && calendarConnectionIsHealthy(calendarConnection),
        google_sync_enabled: destination === "calendar" && calendarConnectionIsHealthy(calendarConnection),
        notes: joinReminderNotesMetadata(notes, meta),
        personId,
        person_id: personId,
        recurrence,
        reminderDate,
        reminder_date: reminderDate,
        reminderType,
        reminder_type: reminderType,
        title: reminderType === "custom" ? `${tagLabel}: ${visibleTitle}` : visibleTitle,
      },
    };
  }

  async function savePersonReminderRecords(formData: FormData, personId: string) {
    const requests: Array<{ method: "PATCH" | "POST"; payload: Record<string, unknown> }> = [];
    const anniversaryRequest = personAnniversaryReminderRequest(formData, personId);
    const importantDateRequest = importantDateReminderRequest(formData, personId);

    if (anniversaryRequest) {
      requests.push(anniversaryRequest);
    }

    if (importantDateRequest) {
      requests.push(importantDateRequest);
    }

    for (const request of requests) {
      const result = await submitJson("/api/dos/app/reminders", request.payload, request.method, false);

      if (!result) {
        return false;
      }
    }

    return true;
  }

  function handleUsamApplicationSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setErrorMessage("");
    setUsamApplicationMessage(null);

    if (isPreview) {
      setErrorMessage("Preview mode is read-only. Applications are not submitted.");
      return;
    }

    void (async () => {
      setIsSubmittingUsamApplication(true);

      try {
        const response = await fetch("/api/dos/app/organization/usam/apply", {
          body: JSON.stringify({
            ...usamApplicationDraft,
            callingFocus: buildUsamApplicationCallingFocus(usamApplicationDraft),
            workspaceId: data.workspace.id,
          }),
          headers: {
            "Content-Type": "application/json",
          },
          method: "POST",
        });
        const result = await response.json().catch(() => ({})) as {
          applicationId?: string;
          error?: string;
          status?: DosAppData["usamApplication"]["status"];
          submittedAt?: string;
        };

        if (!response.ok) {
          throw new Error(result.error ?? "Unable to submit USA Missionaries application.");
        }

        setUsamApplication((currentApplication) => ({
          ...currentApplication,
          applicationId: result.applicationId ?? currentApplication.applicationId,
          appliedAt: result.submittedAt ?? new Date().toISOString(),
          profileStatus: "under_review",
          publicProfileLive: false,
          status: result.status ?? "pending_review",
        }));
        setUsamApplicationMessage({
          text: "Application submitted for review.",
          tone: "success",
        });
        setIsUsamApplicationOpen(false);
        router.refresh();
      } catch (error) {
        setErrorMessage(error instanceof Error ? error.message : "Unable to submit USA Missionaries application.");
      } finally {
        setIsSubmittingUsamApplication(false);
      }
    })();
  }

  function handleDisconnectCalendar() {
    setErrorMessage("");

    if (isPreview) {
      setErrorMessage("Preview mode is read-only. Google Calendar stays connected in the demo.");
      return;
    }

    if (!calendarConnection.connected || isCalendarDisconnecting) {
      return;
    }

    if (!window.confirm("Disconnect Google Calendar? DOS tables and reminders will keep saving locally.")) {
      return;
    }

    setIsCalendarDisconnecting(true);

    void (async () => {
      try {
        const response = await fetch("/api/dos/app/calendar/google/disconnect", {
          body: JSON.stringify({
            workspaceId: data.workspace.id,
          }),
          headers: {
            "Content-Type": "application/json",
          },
          method: "POST",
        });
        const result = await response.json().catch(() => ({})) as { error?: string };

        if (!response.ok) {
          throw new Error(result.error ?? "Unable to disconnect Google Calendar.");
        }

        router.refresh();
      } catch {
        setErrorMessage("Unable to disconnect Google Calendar. Please try again.");
      } finally {
        setIsCalendarDisconnecting(false);
      }
    })();
  }

  function handleSyncGoogleCalendar() {
    setErrorMessage("");
    setCalendarSyncMessage("");

    if (isPreview) {
      setCalendarSyncMessage("Preview mode does not sync live Google events.");
      return;
    }

    if (!calendarConnection.connected || isSyncingGoogleCalendar) {
      setCalendarSyncMessage("Connect Google Calendar to read events.");
      return;
    }

    if (calendarConnectionNeedsReconnect(calendarConnection)) {
      setCalendarSyncMessage(googleCalendarReconnectCopy);
      return;
    }

    setIsSyncingGoogleCalendar(true);

    void (async () => {
      try {
        const syncStart = addCalendarMonths(meetingsCalendarMonth, -1);
        const syncEnd = addCalendarMonths(meetingsCalendarMonth, 4);
        const response = await fetch("/api/dos/app/calendar/google/sync", {
          body: JSON.stringify({
            timeMax: syncEnd.toISOString(),
            timeMin: syncStart.toISOString(),
            workspaceId: data.workspace.id,
          }),
          headers: {
            "Content-Type": "application/json",
          },
          method: "POST",
        });
        const result = await response.json().catch(() => ({})) as {
          error?: string;
          eventCount?: number;
          message?: string | null;
          status?: string;
        };

        if (!response.ok) {
          throw new Error(result.error ?? "Unable to sync Google Calendar.");
        }

        if (result.status === "needs_reconnect" || result.status === "not_connected") {
          setCalendarSyncMessage(result.status === "needs_reconnect" ? result.message ?? googleCalendarReconnectCopy : result.message ?? "Connect Google Calendar to read events.");
          setCalendarConnectionOverride((current) => ({
            ...current,
            status: result.status === "needs_reconnect" ? "needs_reconnect" : "not_connected",
            statusMessage: result.status === "needs_reconnect" ? result.message ?? googleCalendarReconnectCopy : null,
          }));
          return;
        }

        setCalendarSyncMessage(`Synced ${result.eventCount ?? 0} Google events.`);
        router.refresh();
      } catch {
        setCalendarSyncMessage("Unable to sync Google Calendar events.");
      } finally {
        setIsSyncingGoogleCalendar(false);
      }
    })();
  }

  function sourceHasImportedGoogleEvents(source: CalendarSourcePreference) {
    return data.externalCalendarEvents.some((event) => (
      !event.importedMeetingId && calendarSourceMatchesEvent(source, event)
    ));
  }

  function shouldSyncGoogleCalendarOverlays(source?: CalendarSourcePreference) {
    if (isPreview || !calendarConnectionIsHealthy(calendarConnection) || isSyncingGoogleCalendar) {
      return false;
    }

    if (source) {
      return !sourceHasImportedGoogleEvents(source) || !source.lastSyncedAt;
    }

    const selectedSources = calendarSourcePreferences.filter((item) => calendarSourceIsSelected(calendarDisplaySettings, item));

    if (!selectedSources.length) {
      return false;
    }

    return selectedSources.some((item) => !sourceHasImportedGoogleEvents(item) || !item.lastSyncedAt);
  }

  function syncGoogleCalendarOverlaysIfNeeded(source?: CalendarSourcePreference) {
    if (!shouldSyncGoogleCalendarOverlays(source)) {
      return;
    }

    handleSyncGoogleCalendar();
  }

  function handleToggleCalendarCoreSource(source: CalendarCoreSource) {
    const willEnable = !calendarDisplaySettings[source];

    setCalendarDisplaySettings((current) => ({
      ...current,
      [source]: !current[source],
    }));

    if (source === "calendars" && willEnable) {
      syncGoogleCalendarOverlaysIfNeeded();
    }
  }

  function handleToggleGoogleCalendarSource(sourceId: string) {
    const source = calendarSourcePreferences.find((item) => item.id === sourceId);

    if (!source) {
      return;
    }

    const currentSelected = calendarSourceIsSelected(calendarDisplaySettings, source);
    const nextSelected = !currentSelected;

    setCalendarSourceMessage("");
    setCalendarDisplaySettings((current) => ({
      ...current,
      googleSources: {
        ...current.googleSources,
        [sourceId]: nextSelected,
      },
    }));
    setCalendarSourcePreferences((current) => current.map((item) => (
      item.id === sourceId ? { ...item, selectedForDisplay: nextSelected } : item
    )));

    if (nextSelected) {
      syncGoogleCalendarOverlaysIfNeeded(source);
    }

    if (!source.canPersist || isPreview) {
      setCalendarSourceMessage("Source display is local for now.");
      return;
    }

    setSavingCalendarSourceId(sourceId);

    void (async () => {
      try {
        const response = await fetch("/api/dos/app/calendar/sources", {
          body: JSON.stringify({
            selectedForDisplay: nextSelected,
            sourceId,
            workspaceId: data.workspace.id,
          }),
          headers: {
            "Content-Type": "application/json",
          },
          method: "PATCH",
        });
        const result = await response.json().catch(() => ({})) as { error?: string };

        if (!response.ok) {
          throw new Error(result.error ?? "Unable to save calendar source display.");
        }
      } catch {
        setCalendarSourceMessage("Unable to save source display. This view was updated locally.");
      } finally {
        setSavingCalendarSourceId((current) => current === sourceId ? null : current);
      }
    })();
  }

  function handleAddExternalEventToDos() {
    if (!selectedExternalCalendarEvent || isAddingExternalEventToDos) {
      return;
    }

    setErrorMessage("");

    if (isPreview) {
      setErrorMessage("Preview mode is read-only. Google events are not added to DOS.");
      return;
    }

    setIsAddingExternalEventToDos(true);

    void (async () => {
      try {
        const response = await fetch(`/api/dos/app/calendar/events/${selectedExternalCalendarEvent.id}/add-to-dos`, {
          body: JSON.stringify({
            workspaceId: data.workspace.id,
          }),
          headers: {
            "Content-Type": "application/json",
          },
          method: "POST",
        });
        const result = await response.json().catch(() => ({})) as {
          error?: string;
          meetingId?: string;
          message?: string;
          status?: "added" | "already_added";
        };

        if (!response.ok) {
          throw new Error(result.error ?? "Unable to add Google event to DOS.");
        }

        if (result.status === "already_added") {
          setErrorMessage(result.message ?? "Already added to DOS.");
        }

        if (result.meetingId) {
          setSelectedExternalCalendarEventId(null);
          setSelectedMeetingId(result.meetingId);
          setActiveTab("meetings");
        }

        router.refresh();
      } catch (error) {
        setErrorMessage(error instanceof Error ? error.message : "Unable to add Google event to DOS.");
      } finally {
        setIsAddingExternalEventToDos(false);
      }
    })();
  }

  async function handlePeopleImport(rows: PeopleImportRow[]) {
    setPeopleImportMessage(null);

    if (isPreview) {
      throw new Error("Preview mode is read-only. Contacts are not imported.");
    }

    const response = await fetch("/api/dos/app/people/import", {
      body: JSON.stringify({
        rows,
        workspaceId: data.workspace.id,
      }),
      headers: {
        "Content-Type": "application/json",
      },
      method: "POST",
    });
    const result = await response.json().catch(() => ({})) as Partial<PeopleImportResult> & { error?: string };

    if (!response.ok) {
      throw new Error(result.error ?? "Unable to import contacts.");
    }

    const importResult: PeopleImportResult = {
      duplicateCount: result.duplicateCount ?? 0,
      importedCount: result.importedCount ?? 0,
      invalidCount: result.invalidCount ?? 0,
      skippedCount: result.skippedCount ?? 0,
    };

    setPeopleImportMessage({
      text: `Imported ${importResult.importedCount}. Skipped ${importResult.skippedCount}.`,
      tone: "success",
    });
    router.refresh();

    return importResult;
  }

  async function handleCreateMeetingPerson(rawName: string) {
    const nameParts = splitNameParts(rawName);
    const name = joinNameParts(nameParts.firstName, nameParts.lastName);

    if (!name || isCreatingMeetingPerson) {
      return;
    }

    setErrorMessage("");
    setIsCreatingMeetingPerson(true);

    try {
      const createdAt = new Date().toISOString();

      if (isPreview) {
        const previewPersonId = `preview-person-${Date.now()}`;

        setQuickAddedPeople((current) => [
          ...current,
          {
            church: null,
            createdAt,
            discipleshipRelationship: null,
            discipleshipStage: "not_started",
            email: null,
            engagementLevel: "0",
            fieldVisibility: "primary",
            id: previewPersonId,
            lastActivityAt: null,
            name,
            notes: null,
            phone: "",
            relationshipContext: "other",
            relationshipType: "new",
            roleInMyLife: "not_active",
            status: "new",
            updatedAt: createdAt,
          },
        ]);
        setSelectedMeetingPersonIds((current) => current.includes(previewPersonId) ? current : [...current, previewPersonId]);
        setMeetingPeopleQuery("");
        return;
      }

      const response = await fetch("/api/dos/app/people", {
        body: JSON.stringify({
          discipleshipStage: "not_started",
          discipleshipRelationship: "",
          engagementScore: 0,
          name,
          phone: "",
          relationshipContext: "other",
          relationshipType: "new",
          roleInMyLife: "not_active",
          workspaceId: data.workspace.id,
        }),
        headers: {
          "Content-Type": "application/json",
        },
        method: "POST",
      });
      const result = await response.json().catch(() => ({})) as { error?: string; id?: string };

      if (!response.ok || !result.id) {
        throw new Error(result.error ?? "Unable to add person.");
      }

      setQuickAddedPeople((current) => [
        ...current,
        {
          church: null,
          createdAt,
          discipleshipRelationship: null,
          discipleshipStage: "not_started",
          email: null,
          engagementLevel: "0",
          fieldVisibility: "primary",
          id: result.id as string,
          lastActivityAt: null,
          name,
          notes: null,
          phone: "",
          relationshipContext: "other",
          relationshipType: "new",
          roleInMyLife: "not_active",
          status: "new",
          updatedAt: createdAt,
        },
      ]);
      setSelectedMeetingPersonIds((current) => current.includes(result.id as string) ? current : [...current, result.id as string]);
      setMeetingPeopleQuery("");
      router.refresh();
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to add person.");
    } finally {
      setIsCreatingMeetingPerson(false);
    }
  }

