  function meetingRolePayload(formData: FormData, fallbackMeeting?: DosAppMeeting | null) {
    const tableRole = normalizeTableRole(formData.get("table_role") ?? selectedTableRole);

    return {
      ...tableRoleReflectionPayload(formData, tableRole, fallbackMeeting),
      ministryTeamMemberIds: selectedMinistryTeamMemberIds,
      ministryTeamPersonIds: selectedMinistryTeamPersonIds,
      participantPersonIds: selectedMeetingPersonIds,
      supportingAttendees: selectedSupportingAttendeeIds.map((personId) => ({
        personId,
        subRole: supportingAttendeeSubRoles[personId] || null,
      })),
    };
  }

  function handleConversationResponse(questionId: string, value: DosConversationResponseValue | undefined) {
    setConversationResponses((current) => {
      if (value === undefined || value === "") {
        const { [questionId]: _removed, ...rest } = current;

        return rest;
      }

      return {
        ...current,
        [questionId]: value,
      };
    });
  }

  function handleConversationFollowUpAction(actionId: string) {
    setConversationResponses((current) => {
      const currentActions = responseAsStringArray(current.followUpActions);
      const nextActions = currentActions.includes(actionId)
        ? currentActions.filter((currentAction) => currentAction !== actionId)
        : [...currentActions, actionId];

      if (!nextActions.length) {
        const { followUpActions: _removed, ...rest } = current;

        return rest;
      }

      return {
        ...current,
        followUpActions: nextActions,
      };
    });
  }

